/* EP Simulator — course track: acute arrhythmia management, drugs versus electricity (units m1–m6).
 * See docs/COURSE_AUTHORING.md. Every bench is the static 'ecg' bench: the strip is re-simulated from the
 * bench parameters, so "give adenosine", "deliver shock", "atropine" and "pace" are controls that make()
 * turns into scripted events in the HeartSim run (sim.blockAVN, sim.shock, a changed sinus rate, an AAI
 * pacemaker). Each recording carries rec.x: what happened, for check(), live() and the explanations.
 * Doses, energies and time windows are typical teaching values and vary between guidelines and devices.
 */
(function (EP) {
  'use strict';
  const C = EP.Course, S = C.S, R = EP.Rhythms, Mo = EP.Morph;
  const { para, list } = C.T, { pick, shuffle } = C.util;
  const look = S.look, mcq = S.mcq, num = S.num, act = S.act, multi = S.multi;

  // ---- recordings -----------------------------------------------------------------------------------
  const lib = (id) => R.byId[id].cfg({});
  /* Simulate a HeartSim config. o: { warm, dur, script: [{ t, do(sim, t) }] }; script times are simulator times. */
  function record(cfg, o) {
    o = o || {};
    if (o.script) cfg.script = (cfg.script || []).concat(o.script);
    return R.record({ cfg: () => cfg }, { warm: o.warm || 0, dur: o.dur || 10000 });
  }
  const seen = (rec, type) => rec.events.filter((e) => e.type === type && e.t >= rec.t0 && e.t < rec.t1);
  const perMin = (ev) => (ev.length > 1 ? Math.round(60000 * (ev.length - 1) / (ev[ev.length - 1].t - ev[0].t)) : 0);
  const rates = (rec) => ({ vRate: perMin(seen(rec, 'QRS')), aRate: perMin(seen(rec, 'P')) });
  const seg = (rec, type) => rec.segs.some((s) => s.type === type && s.t0 < rec.t1 && s.t1 > rec.t0);
  const sinusBack = (rec) => { const q = seen(rec, 'QRS').slice(-3); return q.length === 3 && !seg(rec, 'vf') && q.every((e) => e.rr > 600 && (e.label === 'conducted' || e.label === 'pre-excited')); };
  /* True when button `k` was pressed with the other settings as they are now. Changing a setting afterwards
   * shows the untreated rhythm again until the button is pressed once more: each press is a fresh attempt. */
  function fired(p, b, k, keys) {
    b = b || {};
    const sig = keys.map((x) => String(p[x])).join('|'), n = p[k] || 0;
    if (!b._f || b._f.spec !== b.spec) b._f = { spec: b.spec, n: 0, sig: '' };
    if (n !== b._f.n) { b._f.n = n; b._f.sig = sig; }
    return n > 0 && b._f.sig === sig;
  }
  const press = (b, k) => b.set(k, (b.p[k] || 0) + 1);
  const memo = {}, once = (k, f) => (k in memo ? memo[k] : (memo[k] = f()));   // numbers quoted in step text: simulated once
  const strip = (make, o) => Object.assign({ kind: 'ecg', layout: 'strip', strips: [1, 6], rowMm: 30, make, measure: rates }, o);
  const sheet = (make, o) => Object.assign({ kind: 'ecg', layout: '12', strips: [1], make, measure: rates }, o);

  // ---- rhythms that the library does not have in this form (sinus node present, so a shock is followed by sinus rhythm)
  const AF = (fib, erp, seed) => ({ seed: seed || 11, sinus: { cl: 870, resp: 0 }, atria: { mode: 'fib', fibMean: fib }, avn: { fast: { erp, conceal: 0.3, min: 60 } } });
  const FLUTTER = (cl, erp) => ({ sinus: { cl: 870, resp: 0 }, atria: { mode: 'flutter', flutterCL: cl }, avn: { fast: { erp: erp || 290, conceal: 0.3 } } });
  const VT = (cl, site) => ({ sinus: { cl: 760, resp: 0 }, avn: { fast: { retro: { block: true } } }, hps: { retro: { delay: 60, erp: 180 } }, foci: [{ id: 'vt', node: 'V', cl, site: site || 'lvInfBase', label: 'VT', startAt: 60, reentrant: true }] });
  const WPWAF = (erp, nodeBlocked, seed) => ({ seed: seed || 11, sinus: { cl: 870, resp: 0 }, atria: { mode: 'fib', fibMean: 120 }, avn: { fast: { erp: 330, conceal: 0.4, block: !!nodeBlocked } }, ap: R.apCfg('leftLateral', { erp }) });
  const PMVT = () => ({ sinus: { cl: 700, resp: 0 }, avn: { fast: { retro: { block: true } } }, script: R.onBeats([{ beat: 4, coupling: 285, site: 'lvAntWall', then: (s, t) => s.schedule(t + 120, (tt) => s.setVentMode('pmvt', tt)) }]) });

  // ===== m1: the defibrillator =======================================================================
  const DEFIB = [{ k: 'sync', label: 'Synchronised mode', toggle: true }, { k: 'j', label: 'Energy (biphasic)', opts: [[50, '50 J'], [100, '100 J'], [150, '150 J'], [200, '200 J']] }, { k: 'shock', label: 'Deliver shock', button: true }];
  /* Unstable tachyarrhythmias. need = energy that converts on this bench (a typical value, not a rule). */
  const UNSTABLE = {
    af: { cfg: () => AF(130, 240), warm: 1000, need: 150, typical: 'atrial fibrillation typically 120–200 J (many centres start at the maximum)',
      who: 'A 74-year-old has been breathless for two hours. She is sitting upright with crackles to the mid-zones, blood pressure 76/48 mmHg and SpO₂ 86 % on high-flow oxygen. Yesterday she was well.' },
    vt: { cfg: () => VT(300), warm: 2000, need: 100, typical: 'monomorphic VT with a pulse typically 100–150 J',
      who: 'A 62-year-old with an old inferior infarct has crushing chest pain. He is grey and clammy, blood pressure 68/40 mmHg, and rouses only to voice. There is a carotid pulse.' },
    fl: { cfg: () => FLUTTER(207), warm: 2000, need: 50, typical: 'atrial flutter and regular narrow-complex tachycardia typically 50–100 J',
      who: 'A 70-year-old with severe aortic stenosis has had central chest pain since his pulse became fast an hour ago. Blood pressure 72/44 mmHg, cold hands, ST depression on the monitor.' },
  };
  /* p: { sync, j, shock }. Synchronised: delivered on the next R wave. Unsynchronised into an organised rhythm:
   * shown at its worst, on the T wave. rec.x = { fired, done, ok (converted), vf } */
  const defib = (rh) => (p, b) => {
    const on = fired(p, b, 'shock', ['sync', 'j']), T0 = rh.warm + 4300, x = { fired: on, done: false, ok: false, vf: false };
    const rec = record(rh.cfg(), { warm: rh.warm, dur: 10000, script: [{ t: 0, do: (s) => {
      if (p.sync) s.on('V0', (e) => s.emit({ t: e.t + 30, type: 'mark', ch: 'V', text: '▲' }));
      if (!on) return;
      const give = (t, onT) => {
        if (onT) { s.emit({ t, type: 'shock', j: p.j }); x.vf = true; s.schedule(t + 50, (tt) => s.setVentMode('vf', tt)); return; }
        if (p.j >= rh.need) { s.shock(t, { j: p.j, sync: !!p.sync }); x.ok = true; } else s.emit({ t, type: 'shock', j: p.j });
      };
      if (p.sync) s.on('V0', (e) => { if (!x.done && e.t >= T0) { x.done = true; s.schedule(e.t + 45, (t) => give(t, false)); } });
      else s.on('V', (ev) => { if (!x.done && ev.t >= T0) { x.done = true; s.schedule(ev.t + ev.wave.qrsOff + 0.72 * ev.wave.jt - 35, (t) => give(t, true)); } });
    } }] });
    rec.x = x; return rec;
  };
  const defibBench = (rh, o) => strip(defib(rh), Object.assign({ p: { sync: false, j: 50, shock: 0 }, ctl: DEFIB, markers: true, title: 'Monitor and defibrillator',
    read: (rec, p, m) => [['Mode', p.sync ? 'synchronised' : 'not synchronised'], ['Energy', p.j, 'J'], ['Ventricular rate now', seg(rec, 'vf') ? 'VF' : perMin(seen(rec, 'QRS').slice(-4)), seg(rec, 'vf') ? '' : '/min']] }, o));
  /* Sinus rhythm and a small shock placed p.at ms after the start of a QRS: how VF is induced to test an ICD. */
  function tShock(p, b) {
    const on = fired(p, b, 'shock', ['at']), x = { fired: on, vf: false };
    let last = null, done = false;
    const rec = record({ sinus: { cl: 857, resp: 0, sd: 0 } }, { dur: 10000, script: [{ t: 0, do: (s) => {
      s.on('V', (ev) => { last = ev.wave; });
      if (on) s.on('V0', (e) => {
        if (done || e.t < 3900 || !last) return;
        done = true;
        const t = e.t + last.qrsOn + p.at, peak = e.t + last.qrsOff + 0.72 * last.jt;
        x.vf = t > peak - 95 && t < peak + 30;
        s.schedule(t, (tt) => { if (x.vf) { s.emit({ t: tt, type: 'shock', j: 1 }); s.schedule(tt + 40, (t2) => s.setVentMode('vf', t2)); } else s.shock(tt, { j: 1 }); });
      });
    } }] });
    rec.x = x; return rec;
  }
  const VULN = strip(tShock, { p: { at: 0, shock: 0 }, title: 'Sinus rhythm and a timed low-energy shock',
    ctl: [{ k: 'at', label: 'Shock falls this long after the start of the QRS', min: 0, max: 600, step: 20, unit: 'ms' }, { k: 'shock', label: 'Deliver shock', button: true }],
    read: (rec, p) => [['Shock', p.at, 'ms after QRS onset'], ['Result', rec.x.vf ? 'ventricular fibrillation' : rec.x.fired ? 'sinus rhythm resumes' : 'no shock yet']] });

  // ===== m2: adenosine ===============================================================================
  /* A tachycardia and, if `on`, a few seconds of AV-nodal block about 3.4 s into the strip. */
  const adeno = (cfg, warm, on, ms) => record(cfg, { warm, dur: 11000, script: on ? [{ t: warm + 3400, do: (s, t) => s.blockAVN(t, ms || 2800) }] : [] });
  const GIVE = [{ k: 'how', label: 'How it is given', opts: [['slow', 'Cannula in the hand, pushed over 20 s, no flush'], ['fast', 'Antecubital vein, pushed fast, 20 mL flush at once']] }, { k: 'give', label: 'Give adenosine 6 mg', button: true }];
  const ATRIAL = [   // regular narrow tachycardias in which the node is a bystander
    { id: 'fl', cfg: () => lib('flutter-21'), warm: 2000, a: 290, v: 145, what: 'Atrial flutter, conducted 2:1', seen: 'sawtooth flutter waves' },
    { id: 'flcw', cfg: () => lib('flutter-cw'), warm: 2000, a: 279, v: 139, what: 'Atrial flutter, conducted 2:1', seen: 'broad, notched flutter waves' },
    { id: 'at', cfg: () => lib('at'), warm: 5000, a: 165, v: 165, what: 'Focal atrial tachycardia', seen: 'P waves' },
  ];

  // ===== m4: wide-complex tachycardia and a test dose ===============================================
  const WCT = {
    vt: { id: 'vt', cfg: (cl) => Object.assign(VT(cl), { avn: {} }), warm: 3000 },   // 1:1 retrograde conduction: no dissociation, no capture beats to give it away
    svt: { id: 'svt', cfg: () => Object.assign(lib('avnrt'), { hps: { pattern: 'lbbb' } }), warm: 4000 },
    fl: { id: 'fl', cfg: () => Object.assign(FLUTTER(207), { hps: { pattern: 'rbbb' } }), warm: 2000 },
  };
  /* rx: 'none' | 'aden' (AV-nodal block for 2.8 s) | 'ver' (verapamil: lasting nodal block; in VT, collapse). */
  function wctRec(v, cl, rx) {
    const t = v.warm + 3400, script = [];
    if (rx === 'aden') script.push({ t, do: (s, tt) => s.blockAVN(tt, 2800) });
    if (rx === 'ver') script.push({ t: t + 600, do: v.id === 'vt' ? (s, tt) => s.schedule(tt + 3200, (t2) => s.setVentMode('vf', t2)) : v.id === 'svt' ? (s, tt) => s.blockAVN(tt, 3600) : (s) => { s.cfg.avn.fast.erp = 640; } });
    const rec = record(v.cfg(cl), { warm: v.warm, dur: 11000, script });
    rec.x = { rx, vf: seg(rec, 'vf'), sinus: sinusBack(rec) };
    return rec;
  }
  const RVOT = () => ({ sinus: { cl: 800, resp: 0 }, avn: { fast: { retro: { block: true } } }, hps: { retro: { delay: 60, erp: 200 } }, foci: [{ id: 'vt', node: 'V', cl: 345, site: 'rvotSeptal', label: 'VT', startAt: 60 }] });

  // ===== m5: torsades and pacing =====================================================================
  const LQT = (qtc) => ({ qtc, tShape: { p: 0.74, sl: 0.24, sr: 0.12 } });
  /* Acquired long QT, sinus rate 52/min. An early after-depolarisation fires a beat whenever the QT of the
   * preceding beat exceeds `crit`; the second one in a row starts a run. A faster (paced) rate shortens the QT. */
  function torsades(crit, pace) {
    const cfg = { sinus: { cl: 1150, resp: 0, sd: 0 }, vent: { mods: LQT(590) } };
    const rec = record(cfg, { warm: 8600, dur: 14000, script: [{ t: 0, do: (s) => {
      let n = 0;
      if (pace) s._pm = new EP.Pacemaker(s, { mode: 'AAI', lrl: pace, kind: 'temp' });
      s.on('V', (ev) => {
        if (ev.label !== 'conducted' || s.V.mode !== 'normal' || ev.wave.qt <= crit) return;
        n++;
        if (n % 4 === 2) s.schedule(ev.t + ev.wave.qt * 0.86, (t) => s.contribV(t, { type: 'focus', spec: Mo.spec('lvInfApical'), label: 'PVC' }));
        else if (n % 4 === 3) s.schedule(ev.t + ev.wave.qt * 0.9, (t) => {
          if (!s.contribV(t, { type: 'focus', spec: Mo.spec('lvAntWall'), label: 'PVC' })) return;
          s.schedule(t + 150, (tt) => { s.setVentMode('tdp', tt); s.schedule(tt + 3300, (t3) => { if (s.V.mode === 'tdp') s.setVentMode('normal', t3); }); });
        });
      });
    } }] });
    const cyc = pace > 52 ? 60000 / pace : 1150, q = seen(rec, 'QRS').filter((e) => e.label === 'conducted' && Math.abs(e.rr - cyc) < 40);
    rec.x = { tdp: seg(rec, 'tdp'), paced: rec.spikes.some((sp) => sp.captured), qt: q.length ? Math.round(q[0].wave.qt) : null, rate: Math.round(60000 / cyc) };
    return rec;
  }
  const tdpRead = (rec) => [['Rate', rec.x.rate, '/min'], ['QT of a steady beat', rec.x.qt, 'ms'], ['Runs of torsades on this strip', rec.x.tdp ? 'yes' : 'none']];

  // ===== m6: AV block and vagal tone =================================================================
  /* 2:1 AV block at two levels. man: 'none' | 'atr' (atropine: faster sinus node, faster AV node) |
   * 'csm' (carotid sinus massage: slower sinus node, slower AV node). Neither acts on the His-Purkinje system. */
  const BLOCK = {
    nodal: (man) => ({ sinus: { cl: man === 'atr' ? 620 : man === 'csm' ? 900 : 760, sd: 0.004, resp: 0 }, avn: { fast: { erp: man === 'atr' ? 430 : man === 'csm' ? 1250 : 800, conceal: 0.25, min: man === 'atr' ? 125 : man === 'csm' ? 180 : 160 } } }),
    infra: (man) => ({ sinus: { cl: man === 'atr' ? 560 : man === 'csm' ? 1200 : 700, sd: 0.004, resp: 0 }, hps: { erp: 1150, pattern: 'rbbb+lafb' } }),
  };
  function blockRec(level, man) {
    const rec = record(BLOCK[level](man), { warm: 2000, dur: 12000 }), nP = seen(rec, 'P').length, nQ = seen(rec, 'QRS').length, m = R.measure(rec);
    rec.x = { nP, nQ, oneToOne: nP > 3 && nQ >= nP - 1, ratio: nQ >= nP - 1 ? '1:1' : Math.round(nP / Math.max(1, nQ)) + ':1', pr: m.pr, qrs: m.qrs };
    return rec;
  }
  const blockRead = (rec, p, m) => [['Atrial rate', m.aRate, '/min'], ['Ventricular rate', m.vRate, '/min'], ['Conduction', rec.x.ratio], ['PR of conducted beats', rec.x.pr, 'ms'], ['QRS', rec.x.qrs, 'ms']];
  const MAN = [{ k: 'man', label: 'Manoeuvre', opts: [['none', 'None'], ['atr', 'Atropine 1 mg IV'], ['csm', 'Carotid sinus massage']] }];
  const CHB = (escape, atr) => ({ sinus: { cl: atr ? 560 : 720, resp: 0.01 }, hps: { block: true }, foci: [{ id: 'v', node: 'V', cl: escape, site: 'fascPost', label: 'escape', startAt: 400, sd: 0.02 }] });

  // ---------------------------------------------------------------------------------------------------
  const UNITS = [
    { id: 'm1', title: 'The first decision: stable or unstable, synchronised or not', short: 'Stable or unstable', goal: 'Decide whether the rhythm is the cause, whether to use electricity, and how the shock must be delivered.',
      teach: () => [
        para('Every fast rhythm is met with the same three questions, in this order: **Is there a pulse? Is the patient unstable? Is the rhythm the cause?** Only after that does the name of the rhythm matter.'),
        list(['**Unstable** means the circulation is failing now: shock (hypotension with poor perfusion), ischaemic chest pain, acute heart failure or pulmonary oedema, or reduced consciousness. Palpitations, anxiety and a high number on the monitor are not instability.',
          '**The rhythm has to be the cause.** A tachycardia may be the response to the illness: sepsis, bleeding, pulmonary embolism, pain. Ventricular rates below about 150/min seldom cause instability by themselves unless the ventricle is already impaired. **Sinus tachycardia is never cardioverted**: the sinus node is not a circuit, and after a shock it resumes at the same rate within a second or two. Treat the cause.',
          '**Unstable because of a tachyarrhythmia: electricity.** A shock depolarises all excitable myocardium at once, so every re-entrant wavefront meets refractory tissue and stops. It works within a second and does not depend on getting the diagnosis right. Drugs are for stable patients, and for keeping the rhythm afterwards.',
          '**Why the shock is synchronised.** During the T wave part of the ventricle has recovered and part has not: the vulnerable period. A shock that falls there can start re-entry, and the result is ventricular fibrillation. In synchronised mode the defibrillator marks each R wave and delivers on one, well clear of the T wave. If there is a discrete QRS and a pulse, synchronise.',
          '**When it cannot be.** Ventricular fibrillation and polymorphic VT have no consistent R wave: the machine may wait for one and never fire. These, and pulseless VT, are **defibrillated**: unsynchronised, at defibrillation energy. Many defibrillators also leave synchronised mode after each shock, so check before a second attempt.',
          '**Energy** depends on the rhythm and on the device: follow the manufacturer and local policy. Typical first biphasic shocks: atrial flutter and regular narrow-complex tachycardia 50–100 J; atrial fibrillation 120–200 J (many centres now start at the maximum); monomorphic VT with a pulse 100–150 J; VF and pulseless VT 120–200 J, or the maximum if the recommendation is not known. One organised circuit needs less energy than fibrillation.',
          '**Sedation.** A shock is painful. A conscious patient is given brief procedural sedation or anaesthesia, with airway support ready, provided that this does not delay treatment of someone who is about to arrest.'])],
      steps: () => {
        const order = shuffle(['af', 'vt', 'fl']), cv = UNSTABLE[order[0]], tri = UNSTABLE[order[1]];
        const by = pick([
          { bench: strip(() => record(lib('sinus-tachy'), { warm: 1000 }), { cap: 'Temperature 39.6 °C · blood pressure 78/44 mmHg · lactate 5.1 mmol/L' }),
            who: 'A 58-year-old has rigors, a temperature of 39.6 °C, blood pressure 78/44 mmHg and a lactate of 5.1 mmol/L. This is the monitor.',
            parts: [['What is the rhythm doing?', 'Compensating: it is the response to the illness', ['Causing the shock: the rate is above 120/min', 'Causing the shock: any tachycardia cuts filling time', 'Nothing: rate plays no part in cardiac output'], 'Regular, with a P wave before every QRS, at 128/min: sinus tachycardia. Stroke volume has fallen (vasodilatation, relative hypovolaemia) and the rate is what keeps the output up.'],
              ['What do you do?', 'Fluids, antibiotics and source control', ['Synchronised cardioversion at 100 J', 'Metoprolol IV until the rate is under 100/min', 'Adenosine 6 mg by rapid bolus'], 'Slowing a compensatory tachycardia removes the compensation. The rate measures how ill the patient is, and it falls when the cause is treated.'],
              ['What would a synchronised shock do to this rhythm?', 'Nothing lasting: the sinus node resumes as before', ['Convert it to sinus rhythm at about 70/min', 'Stop it, as a shock stops any tachycardia', 'Reset the sinus node to a slower rate for some hours'], 'A shock ends re-entry. The sinus node is an automatic pacemaker driven by sympathetic tone: it is silenced for a second and then carries on. The same is true of other automatic rhythms, such as multifocal atrial tachycardia.']] },
          { bench: strip(() => record(AF(150, 340), { warm: 1000 }), { cap: 'Haemoglobin 62 g/L · blood pressure 82/50 mmHg · melaena' }),
            who: 'An 81-year-old with permanent atrial fibrillation, on apixaban, has passed melaena all night. Haemoglobin 62 g/L, blood pressure 82/50 mmHg. This is the monitor.',
            parts: [['What is the rhythm doing?', 'Little: his usual rhythm, faster because he is bleeding', ['Causing the shock: fast atrial fibrillation with hypotension is unstable', 'Causing the shock: the atrial kick has been lost', 'It cannot be judged without an echocardiogram'], 'Irregular with no P waves, at about 110/min: his long-standing atrial fibrillation, with a rate that reflects hypovolaemia. Nothing about the rhythm is new, and the rate is far below the range that causes shock by itself.'],
              ['What do you do?', 'Blood, reversal of the anticoagulant, endoscopy', ['Synchronised cardioversion at 150 J', 'Diltiazem IV until the rate is back under 80/min', 'Digoxin loading over six hours'], 'Treat the bleeding. Rate control would remove the only compensation he has, and a shock would not change a permanent arrhythmia or the blood volume.'],
              ['At what ventricular rate does a tachyarrhythmia itself usually begin to explain shock?', 'Above about 150/min', ['Above about 100/min', 'Above about 120/min in the elderly', 'Only above 220/min minus age'], 'As a working rule, rates below about 150/min seldom cause instability unless the ventricle is impaired or the valves are stenosed. Below that, look harder for another cause before blaming the rhythm.']] }]);
        const ns = pick([
          { bench: strip(() => record(lib('vf'), { dur: 10000 }), { cap: 'No pulse · CPR in progress · pads on' }), who: 'A 59-year-old on the coronary care unit stops answering in mid-sentence. There is no pulse. CPR has started and the pads are on.' },
          { bench: strip(() => record(PMVT(), { dur: 10000 }), { cap: 'No pulse · CPR in progress · pads on' }), who: 'A 66-year-old with an hour of chest pain becomes unresponsive on the trolley. No pulse can be felt. CPR has started and the pads are on.' }]);
        return [
          look('Three questions before the rhythm has a name', 'A fast, irregular narrow-complex rhythm at about 165/min. Before naming it, ask three things. Is there a pulse? Is the patient unstable: shock, ischaemic chest pain, pulmonary oedema, reduced consciousness? And is this rhythm the cause of that, or the response to something else? The steps that follow give you a patient with each strip.',
            strip(() => record(AF(130, 240), { warm: 1000 }))),
          mcq('unstable-def', 'What "unstable" means', 'A 44-year-old has had this regular rhythm at about 176/min for 40 minutes. Which one finding would make you reach for the defibrillator rather than a drug?',
            ['New confusion with a systolic pressure of 72 mmHg', 'Pounding in the neck and a sense of dread', 'A ventricular rate that has stayed above 170/min', 'A first episode, with onset during exercise'],
            'Instability is a failing circulation: shock, ischaemic chest pain, pulmonary oedema or reduced consciousness that the rhythm is causing. Symptoms, the rate itself and the circumstances of onset do not define it. A stable patient with this rhythm gets a vagal manoeuvre and adenosine (next unit).',
            { bench: strip(() => record(lib('avnrt'), { warm: 4000 })) }),
          multi('triage-bystander', 'Fast heart, sick patient', by.who, by.parts, { bench: by.bench, tDone: 'Fast heart, sick patient: the rhythm as bystander', why: 'A tachycardia can be the response to the illness. Sinus tachycardia is never cardioverted, and a rate below about 150/min seldom explains shock.' }),
          mcq('vulnerable-why', 'Predict: the dangerous moment', 'At ICD implantation, ventricular fibrillation is sometimes induced on purpose to test the device: a small shock is timed to one point of the cardiac cycle in sinus rhythm. Which point, and why?',
            ['The T wave: part of the ventricle has recovered and part has not', 'The QRS: the ventricle is being activated and is most unstable', 'The PR segment: the shock reaches the ventricle through the node', 'Late diastole: fully recovered muscle fibrillates most easily'],
            'On the upstroke and peak of the T wave some cells are excitable again while their neighbours are still refractory. A shock there excites the first and blocks in the second: the conditions for re-entry. During the QRS and ST segment everything is refractory; in diastole everything has recovered.', { bench: VULN }),
          act('vulnerable', 'Find the vulnerable period', 'Find it on the bench. This is sinus rhythm, and the small shock falls wherever you place it after the start of a QRS. Move it, deliver it, and repeat until it induces ventricular fibrillation.', { bench: VULN, keep: true,
            check: (x) => x.rec.x.fired && x.rec.x.vf, solve: (b) => { b.set('at', 260); press(b, 'shock'); },
            live: (x) => (x.rec.x.fired && !x.rec.x.vf ? 'A shock at ' + x.p.at + ' ms: a pause, then sinus rhythm again. Not vulnerable there.' : null), hint: 'Step along the ST segment and on to the upstroke of the T wave.',
            why: 'Only a shock on the T wave, from its upstroke to just past its peak, started fibrillation; earlier or later it did nothing lasting. An unsynchronised shock into an organised rhythm falls at a random point of the cycle, and at fast rates the T wave is a large share of it. Whether fibrillation follows also depends on the strength of the shock (weak shocks are the most dangerous), which the bench does not model.' }),
          look('A synchronised shock', 'Monomorphic VT at 200/min in a patient with a pulse. The triangles under the strip are the sync markers: the defibrillator has found each R wave. When the button is held it delivers on the next marker, so the shock arrives during the QRS, well clear of the T wave: it stops the circuit and cannot fall in the vulnerable period. About a second later the sinus node takes over.',
            defibBench(UNSTABLE.vt, { p: { sync: true, j: 150, shock: 1 }, ctl: [] })),
          act('cardiovert', 'Cardiovert', cv.who + ' The pads are on and a small dose of sedative has been given. Treat on the bench: set the defibrillator and deliver the shock.', { bench: defibBench(cv),
            check: (x, st) => { if (x.rec.x.vf) st.bad = true; return x.rec.x.fired && x.p.sync && x.rec.x.ok && (!st.bad || !!x.p.shown); }, solve: (b) => { b.p.shown = 1; b.set('sync', true); b.set('j', 200); press(b, 'shock'); },
            live: (x, st) => { const r = x.rec.x; return x.p.shown ? null : r.vf ? 'Not synchronised: the shock fell on a T wave, and the rhythm is now ventricular fibrillation. In a patient this is a cardiac arrest, treated by an immediate unsynchronised shock. Use "Show me" to see the settings that should have been used.' : st.bad ? 'The unsynchronised shock has already caused ventricular fibrillation. Use "Show me" to see the settings that should have been used.' : !r.fired ? null : !r.ok ? 'Delivered on the R wave, but the rhythm continues: ' + x.p.j + ' J was not enough for this rhythm. Escalate.' : null; },
            hint: 'There is a QRS and a pulse. And the first energy offered is not right for every rhythm.',
            why: 'Synchronised, because there is a discrete QRS and a pulse. Energy by rhythm and device: ' + cv.typical + '. If the first shock fails, escalate. Sedation is given when it causes no delay; this patient cannot wait for a drug to work.' }),
          mcq('sync-reset', 'The second shock', 'The first synchronised shock for atrial fibrillation fails. You raise the energy and press again. This time there are no markers on the screen, the shock is delivered the instant you press, and the monitor shows ventricular fibrillation. What went wrong?',
            ['The machine had left synchronised mode after the first shock', 'The second shock was too strong for an atrial arrhythmia', 'The pads should have been moved before a second attempt', 'The sedation had worn off and the patient moved'],
            'Many defibrillators revert to unsynchronised mode after every shock, so that fibrillation can be treated without delay. Before each further attempt check that synchronisation is on and that there is a marker on every R wave, and not on a tall T wave. The treatment now is an immediate unsynchronised shock.'),
          multi('triage-cause', 'Unknown strip, sick patient', tri.who + ' This is the monitor.', [
            ['Is the rhythm the cause of the patient’s state, or its result?', 'The cause: fast, new, and nothing else explains it', ['The result: treat the illness and the rate will settle', 'Unknowable until blood tests and a chest film are back', 'Neither: a rhythm at this rate does not lower output'], 'A new, fast tachyarrhythmia in a patient with shock, ischaemic pain or pulmonary oedema, and no other explanation for them. That is unstable because of the rhythm.'],
            ['Electricity or a drug?', 'Electricity: DC cardioversion now', ['A drug: diltiazem bolus, then reassess', 'A drug: amiodarone infusion over an hour', 'A drug: adenosine by rapid bolus'], 'When the circulation is failing because of a tachyarrhythmia, the treatment does not depend on which one it is. A shock works within a second; every drug takes longer, and most lower the pressure first.'],
            ['How is the shock delivered?', 'Synchronised to the R wave', ['Unsynchronised, because the patient is unstable', 'Unsynchronised, because the rate is so fast', 'Synchronised to the peak of the T wave'], 'There is a discrete QRS and a pulse, so the shock is synchronised: ' + tri.typical + '. Unsynchronised shocks are for rhythms with no R wave to find, and for the pulseless. A conscious patient is sedated first if that causes no delay.'],
          ], { bench: strip(() => record(tri.cfg(), { warm: tri.warm })), tDone: 'Unstable because of the rhythm: synchronised cardioversion', why: 'Unstable because of a tachyarrhythmia with a QRS and a pulse: synchronised cardioversion, whatever the rhythm is called.' }),
          multi('triage-nosync', 'No pulse', ns.who, [
            ['What does the monitor show now?', 'A disorganised rhythm with no consistent QRS', ['A regular wide-complex tachycardia with a clear R wave', 'Atrial fibrillation with a bundle branch block', 'An organised rhythm without a pulse (PEA)'], 'After a few sinus beats an extrasystole falls on a T wave and the rhythm breaks up: there is no repeating QRS, only deflections that change in size and direction. Ventricular fibrillation and pulseless polymorphic VT are treated in the same way.'],
            ['Shock now, or a drug first?', 'Shock now, with CPR up to it and straight after it', ['Amiodarone 300 mg first, then shock', 'Adrenaline 1 mg first, then shock', 'Magnesium 2 g, and reassess in two minutes'], 'Only a shock ends ventricular fibrillation, and every minute of delay costs survival. The drugs are adjuncts for fibrillation that persists after shocks.'],
            ['Synchronised?', 'No: there is no R wave for the machine to find', ['Yes: to keep the shock off the T wave', 'Yes: a synchronised shock needs less energy', 'No: but only because the patient is unconscious'], 'In synchronised mode the defibrillator waits for an R wave. Here it may find none and never fire. Defibrillate: unsynchronised, typically 120–200 J biphasic as the manufacturer advises, or the maximum if that is not known.'],
          ], { bench: ns.bench, tDone: 'No pulse, no R wave: defibrillate', why: 'Ventricular fibrillation and polymorphic VT cannot be synchronised: defibrillate, with CPR either side.' }),
          mcq('energy-order', 'How much energy', 'Which of these rhythms usually converts with the least energy?', ['Atrial flutter', 'Atrial fibrillation', 'Ventricular fibrillation', 'Polymorphic ventricular tachycardia'],
            'Flutter is a single circuit with an excitable gap: depolarise the gap and it is over, typically with 50–100 J. Fibrillation is many wavelets, and nearly all of the muscle has to be captured at once: typically 120–200 J or more. The numbers are typical and differ between devices; the ordering is the principle.'),
        ];
      } },

    { id: 'm2', title: 'Regular narrow-complex tachycardia', short: 'Narrow-complex tachycardia', goal: 'Use vagal manoeuvres and adenosine as treatment and as a test, and read what the response means.',
      teach: () => [
        para('A regular narrow-complex tachycardia in a stable patient is one of three things: a re-entrant circuit that includes the AV node (AVNRT, orthodromic AVRT), an atrial rhythm that merely passes through the node (flutter, atrial tachycardia), or sinus tachycardia. **The treatment is also the test: block the AV node for a few seconds and watch.**'),
        list(['**Node in the circuit:** one blocked impulse breaks the loop and the tachycardia stops. **Node as bystander:** the atrial rhythm carries on, the ventricles pause, and the atrial activity is laid bare. Either answer is useful, so run a strip (better, a 12-lead) while you do it.',
          '**Vagal manoeuvres first.** The vagus releases acetylcholine on to the AV node; it opens a potassium channel, hyperpolarises the cells and slows or blocks conduction. The **modified Valsalva** (strain for 15 s at about 40 mmHg, semi-recumbent, then at once lie flat with the legs lifted) converts about four in ten, against one in six for the standard manoeuvre. Carotid sinus massage is one side at a time, and not with a bruit or a previous stroke.',
          '**Adenosine** acts on A1 receptors and opens the same potassium channel: a few seconds of AV-nodal block. It is cleared from blood by red cells and endothelium with a half-life under 10 seconds, so it has to arrive as a bolus: a large proximal vein, a rapid push, an immediate flush. Typical doses are 6 mg, then 12 mg (some algorithms allow a further 12 or 18 mg).',
          '**Dose modifiers.** Start lower, about 3 mg, through a central venous line, with dipyridamole (it blocks uptake) or carbamazepine, and in a transplanted, denervated heart. More may be needed with theophylline or caffeine, which block the receptor.',
          '**Warn the patient** of flushing, chest tightness and a feeling of doom for 10–20 seconds. **Avoid or take care** in asthma with active bronchospasm, in second- or third-degree AV block or sinus node disease without a pacemaker, and in any irregular wide-complex tachycardia. Adenosine also shortens atrial refractoriness and provokes atrial fibrillation in a few per cent, which matters if there is an accessory pathway: have a defibrillator within reach.',
          '**Second line**, if the tachycardia does not stop or keeps returning: IV verapamil or diltiazem, or a beta-blocker. Same node, longer block. Not verapamil or diltiazem with hypotension, impaired left ventricular function, a tachycardia that might be VT or pre-excited AF, or on top of an IV beta-blocker.',
          '**Unstable at any point:** synchronised cardioversion.'])],
      steps: () => {
        const AV = strip((p) => adeno(lib('avnrt'), 4000, false), { ladder: true });
        const GV = strip((p, b) => { const on = fired(p, b, 'give', ['how']), works = on && p.how === 'fast', rec = adeno(lib('avnrt'), 4000, works); rec.x = { on, works, sinus: sinusBack(rec) }; return rec; }, { p: { how: 'slow', give: 0 }, ctl: GIVE, ladder: true });
        const dose = pick([
          ['The 6 mg was given correctly and did nothing at all. What is the typical next dose?', 12, 0.5, '12 mg. The usual sequence is 6 mg, then 12 mg; some algorithms allow a further 12 or 18 mg. If adenosine that was properly given changes nothing, question the diagnosis before repeating it.'],
          ['The same tachycardia in a patient whose only venous access is a central line. What is the typical first dose?', 3, 1, 'About 3 mg, half the usual dose: through a central line the bolus reaches the heart undiluted. The same reduction is used with dipyridamole (which blocks adenosine uptake) or carbamazepine and in a transplanted heart, and some would start lower still. Theophylline and caffeine do the opposite.']]);
        const u = pick(ATRIAL), age = pick([52, 61, 67, 73]);
        const UK = (given) => strip((p) => { const rec = adeno(u.cfg(), u.warm, p.aden > 0); rec.x = { a: u.a }; return rec; }, { wide: true, p: { aden: given }, ctl: given ? [] : [{ k: 'aden', label: 'Give adenosine 6 mg (rapid bolus, flushed)', button: true }],
          read: () => [['Ventricular rate before', u.v, '/min'], ['Atrial rate during the pause', u.a, '/min']] });
        const fl = u.id !== 'at';
        return [
          look('The node as part of the circuit', 'Regular, narrow, about 176/min, and no P wave in front of the QRS. Look at the end of the QRS in V1: a small extra positive deflection that will not be there in sinus rhythm. It is the atria, activated backwards at almost the same moment as the ventricles. The ladder diagram shows why: the impulse travels down one AV-nodal pathway and back up the other, once per beat. The AV node is not a bystander here. It is the circuit.', AV),
          mcq('aden-predict', 'Predict: block the node', 'This regular narrow-complex tachycardia at 176/min is AV-nodal re-entry. You are about to block conduction through the AV node for a few seconds. What will the strip show?',
            ['It stops within a beat; a pause, then sinus rhythm', 'The ventricles pause while the atria continue at 176/min', 'The rate falls gradually over a minute, then climbs back', 'No change: a narrow-complex circuit does not need the node'],
            'The node is a limb of the circuit, so one blocked impulse ends it. Gradual slowing and speeding is how sinus tachycardia answers; a ventricular pause with continuing atrial activity is how flutter and atrial tachycardia answer.', { bench: AV, keep: true }),
          mcq('vagal-how', 'First, the vagus', 'Before any drug, a vagal manoeuvre. Which description is the modified Valsalva, the version that converts about four in ten?',
            ['Strain for 15 s semi-recumbent, then lie flat with the legs raised', 'Strain for 15 s sitting upright, then stay sitting and breathe out', 'Press on both carotid sinuses at once for 10 s while supine', 'Hold the breath for 30 s, then cough hard three times while standing'],
            'Straining (about 40 mmHg: blowing into a 10 mL syringe hard enough to move the plunger), then lying flat with the legs lifted, gives a surge of venous return and pressure on release, and the baroreflex answers with a burst of vagal discharge on the AV node. In the REVERT trial this converted 43 % against 17 % for the standard manoeuvre. Carotid massage is never bilateral.'),
          act('aden-give', 'Give adenosine', 'A stable 28-year-old has this regular narrow-complex tachycardia, and the Valsalva has failed. Terminate it with adenosine 6 mg: choose how it is given, then give it.', { bench: GV,
            check: (x) => x.rec.x.works && x.rec.x.sinus, solve: (b) => { b.set('how', 'fast'); press(b, 'give'); },
            live: (x) => (x.rec.x.on && !x.rec.x.works ? 'No effect. The half-life of adenosine in blood is under 10 seconds: it was gone before it reached the heart.' : null), hint: 'How long does adenosine survive in the bloodstream?',
            why: 'Adenosine is taken up by red cells and endothelium within seconds, so it works only as a bolus: a large proximal vein, a fast push and an immediate flush. The commonest cause of "adenosine-resistant" SVT is the injection. On the strip: the last tachycardia beat, then sinus P waves that are not conducted while the node is still blocked, then sinus rhythm.' }),
          num('aden-dose', 'The dose', dose[0], dose[1], dose[2], 'mg', dose[3]),
          num('reveal-rate', 'Adenosine as a test', 'A ' + age + '-year-old has a regular narrow-complex tachycardia at ' + u.v + '/min and is stable. The modified Valsalva did nothing. Give adenosine on the bench. What is the atrial rate while the ventricles pause?', u.a, 20, '/min',
            (fl ? 'About ' + u.a + '/min: ' + u.seen + ' run straight through the pause, one every ' + Math.round(60000 / u.a) + ' ms. The ventricular rate of ' + u.v + '/min was exactly half of this. ' : 'About ' + u.a + '/min: the ' + u.seen + ' march on through the pause at the rate they had before, and only the QRS complexes are missing. ') + 'Nothing was terminated, and that is the result: the atrial rhythm does not need the node.', { bench: UK(0) }),
          multi('reveal-means', 'What the response means', 'A stable patient with a regular narrow-complex tachycardia at ' + u.v + '/min has been given adenosine. The strip shows the response.', [
            ['What did adenosine do?', 'Blocked the node; the atrial rhythm carried on', ['Stopped the tachycardia, which then restarted', 'Slowed the atria and the ventricles together', 'Nothing: the dose was too small to act'], 'The QRS complexes stop for a few seconds and the atrial activity continues at an unchanged rate. When the node recovers the ventricular rate returns to what it was.'],
            ['So the mechanism is…', u.what, ['AV-nodal re-entry (AVNRT)', 'Orthodromic AV re-entry (AVRT)'].concat(fl ? ['Sinus tachycardia with a long PR'] : ['Atrial fibrillation']), fl ? 'Continuous atrial activity near 300/min with no flat baseline, conducted 2:1: flutter. A regular narrow tachycardia close to 150/min is flutter until proved otherwise.' : 'Discrete P waves at ' + u.a + '/min with a flat baseline between them, unaffected by AV block: a focal atrial tachycardia. A node-dependent circuit would have stopped.'],
            ['What next?', fl ? 'Rate control or cardioversion, as for AF' : 'A beta-blocker, verapamil or diltiazem', fl ? ['Adenosine again at 12 mg, and then at 18 mg', 'Nothing more: the test has treated it', 'Flecainide alone, to slow the atria'] : ['Adenosine again at 12 mg, and then at 18 mg', 'Nothing more: the test has treated it', 'Anticoagulation alone, and review in a month'],
              fl ? 'More adenosine will show the same thing again. Flutter is managed like atrial fibrillation (next unit): slow the ventricles or cardiovert, with the same attention to thrombo-embolic risk. A class Ic drug alone can make it conduct 1:1.' : 'More adenosine will usually show the same thing again (a minority of focal atrial tachycardias do stop with it). A beta-blocker, verapamil or diltiazem slows the ventricles and may suppress the focus; cardioversion if the patient becomes unstable.'],
          ], { bench: UK(1), tDone: 'Adenosine as a test: ' + u.what.toLowerCase(), why: 'Termination means the node was in the circuit. AV block with continuing atrial activity means flutter or atrial tachycardia.' }),
          mcq('delta-after', 'Look at the beats after the pause', 'A different patient, 19 years old: a regular narrow-complex tachycardia at 199/min that adenosine has just stopped. Look at the sinus beats after the pause: at first they are wide with a short PR, and then they narrow. What have you learned?',
            ['There is an accessory pathway: the circuit was AVRT', 'The right bundle is slow to recover: aberrancy', 'The adenosine has caused transient ischaemia', 'Ventricular escape beats are covering the pause'],
            'A short PR and a wide, slurred QRS: a delta wave, largest while the node is still blocked and the whole ventricle is activated over the pathway, and shrinking as the node recovers. Two consequences. Adenosine provokes atrial fibrillation in a few per cent of patients, and atrial fibrillation over a pathway can be very fast: this is why a defibrillator is kept within reach. And this patient needs an electrophysiology referral.',
            { bench: strip(() => adeno(lib('avrt'), 4000, true, 2400), { wide: true }) }),
          mcq('asthma', 'When adenosine is the wrong drug', 'A 31-year-old with poorly controlled asthma, wheezy today, has a regular narrow-complex tachycardia at 185/min. Blood pressure 122/76 mmHg; the heart was normal on an echocardiogram last year. Vagal manoeuvres have failed. Best next drug?',
            ['Verapamil IV, given slowly', 'Adenosine 6 mg, then 12 mg', 'Propranolol IV, given slowly', 'Amiodarone IV over an hour'],
            'Adenosine can provoke bronchospasm, so active asthma is the classic reason to avoid it. Verapamil or diltiazem block the same node for longer and are safe for the airways; a non-selective beta-blocker is not. Verapamil is acceptable here because the QRS is narrow, the ventricle is normal and the pressure is good.'),
          mcq('verapamil-stop', 'When verapamil is the wrong drug', 'A regular tachycardia has not responded to vagal manoeuvres or to adenosine, and you consider IV verapamil as second line. Which finding should stop you?',
            ['The QRS is 150 ms wide and he has had an infarct', 'The rate has stayed above 190/min for an hour', 'She is 24 years old and this is her first episode', 'The echocardiogram six months ago was normal'],
            'A wide QRS with structural heart disease is VT until proved otherwise, and the failure of adenosine fits. Verapamil and diltiazem vasodilate and depress contractility without stopping VT. The other reasons to stop are hypotension, impaired left ventricular function, an irregular wide-complex tachycardia, and an IV beta-blocker already given. In a narrow-complex tachycardia with a normal ventricle they are the standard second line.'),
        ];
      } },

    { id: 'm3', title: 'Atrial fibrillation, flutter and pre-excited AF', short: 'AF and flutter', goal: 'Choose rate control by substrate, time a cardioversion safely, and recognise the atrial fibrillation in which AV-nodal blockers are dangerous.',
      teach: () => [
        para('In atrial fibrillation three decisions are made separately: **is the patient unstable because of it** (cardiovert), **what is the thrombo-embolic risk** (anticoagulate), and **rate or rhythm control** for now.'),
        list(['**Rate control is the usual acute strategy** in a stable patient: it is the ventricular rate, not the fibrillating atria, that causes most of the symptoms. The drugs act on the AV node: a beta-blocker or diltiazem / verapamil first, digoxin or amiodarone when those are unsafe. A resting rate below about 110/min is an acceptable first target.',
          '**Choose by substrate.** Preserved ejection fraction: beta-blocker, diltiazem or verapamil. Reduced ejection fraction or decompensated heart failure: no diltiazem or verapamil (negative inotropes); digoxin or IV amiodarone, and a beta-blocker in small doses once congestion has cleared. A low blood pressure: digoxin or amiodarone, and ask again whether the patient is in fact unstable. Bronchospasm: diltiazem or verapamil. High sympathetic drive (thyrotoxicosis, after surgery): a beta-blocker. Digoxin slows the node through the vagus, so it is slow and is overridden by sympathetic tone.',
          '**Cardioversion and stroke.** Thrombus forms in the left atrial appendage during fibrillation, and the atria stay mechanically stunned for days to weeks after sinus rhythm returns, however it returns. The conventional framework: fibrillation for **more than 48 hours, or of unknown duration**, is not cardioverted electively until anticoagulation has been effective for **3 weeks** or a transoesophageal echocardiogram shows no thrombus; anticoagulation then continues for at least **4 weeks** in everyone, and long term according to the stroke risk score, not the rhythm. Recent guidelines have narrowed the window (24 hours in the 2024 European guideline).',
          '**An unstable patient is cardioverted at once**, whatever the duration, with anticoagulation started as soon as possible and continued afterwards.',
          '**Flutter** is one circuit at about 300/min with the node conducting 2:1. Rate control is harder than in fibrillation, cardioversion is easier, and the thrombo-embolic rules are the same. **Class Ic drugs slow the circuit**, and a slower atrial rate can let the node conduct 1:1, so they are given with an AV-nodal blocker.',
          '**Pre-excited atrial fibrillation.** An accessory pathway conducts fibrillation to the ventricles without the node’s filter. The ECG is **irregular, wide and very fast**, and the QRS changes width from beat to beat as conduction over the pathway and over the node fuse in varying proportion. The shortest R-R interval reflects the pathway’s refractory period: 250 ms or less means it can conduct at 240/min or more, fast enough to become ventricular fibrillation.',
          '**AV-nodal blockers are dangerous in pre-excited AF:** adenosine, verapamil, diltiazem, digoxin, beta-blockers, and IV amiodarone given acutely. The node was never the route. Blocking it removes the retrograde concealed penetration by which conducted beats keep the pathway partly refractory; vasodilatation brings reflex sympathetic drive, which shortens the pathway’s refractory period; digoxin shortens it directly. Treat the pathway: **procainamide or ibutilide** if stable, **synchronised cardioversion** if not, or if in doubt.'])],
      steps: () => {
        const afSeed = pick([11, 23, 37]), afB = strip(() => record(AF(135, 250, afSeed), { warm: 1000 }));
        const rc = pick([
          { who: 'A 71-year-old with dilated cardiomyopathy (ejection fraction 25 %) has been more breathless for several days: ankle oedema, basal crackles, blood pressure 102/64 mmHg, warm and alert.',
            drug: ['Which drug to slow the ventricles?', 'Digoxin, or amiodarone IV', ['Diltiazem IV, or verapamil IV', 'Metoprolol 15 mg IV at once', 'Flecainide IV'], 'With a poor ventricle, congestion and a blood pressure that leaves no room for a vasodilator, the choice is between digoxin (slow, and weaker when sympathetic tone is high, but not a negative inotrope) and IV amiodarone (which slows the node acutely; it may also restore sinus rhythm, so the thrombo-embolic rules apply). A beta-blocker is added in small doses once the congestion has cleared. Class Ic drugs are not used in structural heart disease.'],
            not: ['Why not diltiazem?', 'It depresses contractility in a failing ventricle', ['It has no action on the AV node', 'It prolongs the QT interval and causes torsades de pointes', 'It shortens atrial refractoriness'], 'Diltiazem and verapamil are negative inotropes and vasodilators. In systolic heart failure they lower the output further, and guidelines class them as harmful in decompensated failure.'] },
          { who: 'A 66-year-old with asthma and COPD is wheezy today and has had palpitations for two days. Blood pressure 138/82 mmHg; the ejection fraction was normal on an echocardiogram last year.',
            drug: ['Which drug to slow the ventricles?', 'Diltiazem or verapamil', ['Propranolol or carvedilol', 'Sotalol', 'Adenosine'], 'A rate-limiting calcium-channel blocker slows the node and leaves the airways alone. A β1-selective blocker is acceptable in COPD without reversibility, but non-selective ones (propranolol, sotalol, carvedilol) are not for a wheezy patient. Adenosine blocks the node for seconds and can itself cause bronchospasm.'],
            not: ['Why not propranolol?', 'It blocks β2 receptors and can provoke bronchospasm', ['It has no useful action on the AV node', 'It is a positive inotrope and raises the ventricular rate', 'It shortens the QT and causes arrhythmia'], 'Propranolol slows the node well, but it is non-selective: β2 blockade in the airways can precipitate severe bronchospasm in asthma.'] },
          { who: 'A 34-year-old has lost weight and has a tremor, a goitre and a suppressed TSH. Palpitations for a week. Blood pressure 128/70 mmHg, a normal ejection fraction, a clear chest.',
            drug: ['Which drug to slow the ventricles?', 'A beta-blocker', ['Digoxin on its own', 'Amiodarone', 'Flecainide'], 'The node is being driven by adrenergic excess, and a beta-blocker treats that mechanism (and the tremor). Amiodarone would carry an iodine load into a thyrotoxic patient. If a beta-blocker cannot be used, diltiazem or verapamil.'],
            not: ['Why is digoxin alone a poor choice here?', 'Sympathetic drive overrides its vagal action', ['It is contraindicated in any disease of the thyroid', 'It speeds conduction through the AV node', 'It can act only after sinus rhythm returns'], 'Digoxin slows the node mainly by raising vagal tone. That works at rest in a sedentary patient and fails when sympathetic tone is high: exercise, sepsis, thyrotoxicosis, the days after surgery. It also takes hours to act.'] }]);
        const wk = pick([
          ['Atrial fibrillation for about ten days, now rate-controlled and stable. Elective cardioversion is planned without a transoesophageal echocardiogram. For how many weeks, at least, must anticoagulation have been effective beforehand?', 3],
          ['Atrial fibrillation of unknown duration has just been cardioverted after a transoesophageal echocardiogram showed no thrombus. The stroke risk score is zero. For how many weeks, at least, is anticoagulation continued?', 4]]);
        const cl = pick([280, 290, 300, 310, 320]);
        const FL = strip((p) => { let rec = record(FLUTTER(p.cl), { warm: 2000 }); if (perMin(seen(rec, 'QRS')) > 0.8 * 60000 / p.cl) rec = record(Object.assign(FLUTTER(p.cl), { vent: { slow: 1.7 } }), { warm: 2000 }); return rec; }, { wide: true, p: { cl: 200 }, ctl: [{ k: 'cl', label: 'Flutter cycle length (class Ic drugs lengthen it)', min: 200, max: 320, step: 10, unit: 'ms' }],
          measure: (rec, p) => ({ vRate: perMin(seen(rec, 'QRS')), aRate: Math.round(60000 / p.cl) }), read: (rec, p, m) => [['Atrial rate', m.aRate, '/min'], ['Ventricular rate', m.vRate, '/min'], ['Conduction', m.vRate > 0.8 * m.aRate ? '1:1' : '2:1'], ['QRS', Math.round(seen(rec, 'QRS')[2].wave.qrs), 'ms']] });
        const erp = pick([200, 215, 230, 245, 260, 275]), sd = pick([11, 19, 29]);
        const minRR = (rec) => { const q = seen(rec, 'QRS'); let m = 1e9; for (let i = 1; i < q.length; i++) m = Math.min(m, q[i].t - q[i - 1].t); return Math.round(m); };
        const SP = strip(() => { const rec = record(WPWAF(erp, false, sd), { warm: 1000, dur: 8000 }); rec.x = { minRR: minRR(rec) }; return rec; }, { wide: true, strips: [6, 1], rowMm: 38, read: (rec, p, m) => [['Shortest R-R', rec.x.minRR, 'ms'], ['Mean ventricular rate', m.vRate, '/min']] });
        const AP = strip((p) => record(WPWAF(p.erp, p.node, sd), { warm: 1000, dur: 9000 }), { wide: true, strips: [6, 1], rowMm: 38, p: { node: false, erp: 210 },
          ctl: [{ k: 'node', label: 'Block the AV node (adenosine, verapamil, digoxin, beta-blocker)', toggle: true }, { k: 'erp', label: 'Refractory period of the accessory pathway', min: 180, max: 460, step: 10, unit: 'ms' }],
          read: (rec, p, m) => [['Mean ventricular rate', m.vRate, '/min'], ['Shortest R-R', minRR(rec), 'ms'], ['AV node', p.node ? 'blocked' : 'conducting']] });
        const sick = pick([false, true]), fbiErp = pick([205, 215, 225]);
        return [
          look('What the node lets through', 'No P waves, a fine irregular baseline (clearest in V1), and R-R intervals with no pattern: atrial fibrillation, with a ventricular rate of about 155/min. The atria are firing several hundred times a minute, and what you see is what the AV node lets through. That is why the acute drugs for a stable patient are aimed at the node and not at the atria.', afB),
          multi('rate-drug', 'A stable patient', rc.who + ' The rhythm is on the bench.', [
            ['Strategy for the next hour?', 'Control the rate; anticoagulate by stroke risk', ['Cardiovert at once, then anticoagulate', 'Adenosine, to restore sinus rhythm', 'Wait: it will settle without treatment'], 'Stable, and present for days: nothing is gained by restoring sinus rhythm in the next hour, and cardioversion without anticoagulation risks a stroke. Slow the ventricles, deal with the thrombo-embolic risk, and decide about rhythm control afterwards.'],
            rc.drug, rc.not,
          ], { bench: afB, keep: true, tDone: 'Rate control: the drug depends on the patient', why: 'Rate control in a stable patient, with the drug chosen by substrate: heart failure, airways, sympathetic drive.' }),
          num('ac-weeks', 'Anticoagulation around cardioversion', wk[0], wk[1], 0.01, 'weeks',
            'Three weeks before (or a transoesophageal echocardiogram showing no thrombus), and four weeks after for everyone; beyond that, according to the stroke risk score and not the rhythm. The four weeks afterwards exist because the atria are mechanically stunned for days to weeks after sinus rhythm returns, and new thrombus can form then.'),
          mcq('chem-cv', 'A drug instead of a shock', 'Stable atrial fibrillation, onset unknown, not anticoagulated. A colleague proposes IV flecainide or amiodarone to restore sinus rhythm, "because it is not a shock". What is the flaw?',
            ['The embolic risk comes from regaining sinus rhythm by any route', 'Drugs can only convert atrial fibrillation within the first hour', 'Drug conversion needs a general anaesthetic and a fasted patient', 'Antiarrhythmic drugs dissolve thrombus and release it at once'],
            'Thrombus in the appendage is expelled when organised atrial contraction returns, and stunned atria form new thrombus afterwards. That is true of electrical, pharmacological and spontaneous conversion alike. The conventional rule: beyond 48 hours or with unknown duration, no elective cardioversion of either kind without three weeks of anticoagulation or a clear transoesophageal echocardiogram. Recent guidelines have narrowed the window, because the risk rises within the first day.'),
          mcq('toe', 'Sinus rhythm this week', 'Atrial fibrillation for four days, very symptomatic despite rate control, not yet anticoagulated. She wants sinus rhythm this week. Which plan is safe?',
            ['Anticoagulate, exclude thrombus by TOE, cardiovert, continue 4 weeks', 'Cardiovert today: thrombus takes more than a week to form', 'Give a heparin bolus and cardiovert within the hour', 'Aspirin and clopidogrel for three weeks, then cardiovert without imaging'],
            'A transoesophageal echocardiogram (TOE) replaces the three weeks of waiting, not the anticoagulation, which is started before the cardioversion and continued for at least four weeks after it. If thrombus is seen, cardioversion is postponed. Antiplatelet drugs do not protect.'),
          num('flutter-11', 'Flutter and a class Ic drug', 'Typical flutter at 300/min conducts 2:1, so the ventricular rate is 150/min. Flecainide is started without an AV-nodal blocker and slows the circuit to a cycle length of ' + cl + ' ms. If the AV node now conducts every impulse, what is the ventricular rate?', 60000 / cl, 6, '/min',
            '60 000 ÷ ' + cl + ' = ' + Math.round(60000 / cl) + '/min. The drug has slowed the atria and sped up the ventricles. The next step shows why the node lets it happen.'),
          act('flutter-11-do', 'Slow the atria, speed the ventricles', 'Show it on the bench: atrial flutter at 300/min, conducted 2:1. The slider lengthens the flutter cycle, as a class Ic drug does. Slow the circuit until the ventricular rate goes up.', { bench: FL,
            check: (x) => x.p.cl > 200 && x.m.vRate > 165, solve: (b) => b.set('cl', 300),
            live: (x) => (x.p.cl > 200 && x.m.vRate <= 165 ? 'Atrial rate ' + x.m.aRate + '/min, still conducted 2:1: ventricular rate ' + x.m.vRate + '/min. Keep going.' : null), hint: 'The AV node here needs about 290 ms to recover after each impulse it conducts.',
            why: (b) => 'At 300/min every second flutter wave reaches a node that is still refractory, so conduction is 2:1 and the ventricular rate falls as the circuit slows. Once the flutter cycle is longer than the node’s refractory period every wave conducts: here ' + b.m.aRate + '/min in the atria and ' + b.m.vRate + '/min in the ventricles. The QRS has widened as well: sodium-channel block is use-dependent, so the drug slows ventricular conduction most at fast rates (the bench applies this widening whenever conduction is 1:1). A regular wide-complex tachycardia at 200/min is easily mistaken for VT. Flecainide and propafenone are therefore given with a beta-blocker, verapamil or diltiazem.' }),
          look('Fast, broad, irregular', 'Three features together: irregular, wide, and very fast (about 215/min, with some R-R intervals near 220 ms). Follow the rhythm strip: the QRS changes width from beat to beat while its axis stays the same. Each beat is a fusion of conduction over an accessory pathway and over the AV node, in proportions that vary with timing. This is atrial fibrillation conducted over an accessory pathway.',
            sheet(() => record(WPWAF(215, false), { warm: 1000 }))),
          num('sperri', 'The shortest R-R interval', 'Pre-excited atrial fibrillation in another patient. Measure the shortest R-R interval on the strip.', (b) => b.rec.x.minRR, 25, 'ms',
            (b) => b.rec.x.minRR + ' ms, a momentary rate of ' + Math.round(60000 / b.rec.x.minRR) + '/min. The AV node cannot conduct that fast, so the shortest pre-excited R-R interval in atrial fibrillation approximates the refractory period of the pathway. 250 ms or less marks a pathway that can conduct fibrillation fast enough to degenerate into ventricular fibrillation' + (b.rec.x.minRR <= 250 ? ': this one qualifies.' : '; this one is just outside that range, and is treated in the same way.'), { bench: SP }),
          act('ap-erp', 'What protects the ventricles', 'Pre-excited atrial fibrillation, with two things that a drug could change: conduction through the AV node, and the refractory period of the accessory pathway. Use them to bring the mean ventricular rate below 150/min.', { bench: AP,
            check: (x) => !x.p.node && x.m.vRate > 0 && x.m.vRate < 150, solve: (b) => { b.set('node', false); b.set('erp', 400); },
            live: (x) => (x.p.node ? 'AV node blocked: ' + x.m.vRate + '/min, and now every beat is fully pre-excited. The fast beats were not travelling through the node' + (x.m.vRate < 150 ? ', and it is the pathway setting that has slowed them. Let the node conduct again.' : '.') : x.changes ? 'Pathway refractory period ' + x.p.erp + ' ms: ' + x.m.vRate + '/min.' : null), hint: 'Which structure is carrying the fast beats?',
            why: 'Blocking the node does not slow anything here: the fast beats never used it, and on the bench every QRS simply becomes fully pre-excited. In a patient it can be worse, for reasons the model leaves out: conducted beats normally penetrate the pathway backwards and keep it partly refractory; verapamil and diltiazem vasodilate, and reflex sympathetic drive shortens the pathway’s refractory period; digoxin shortens it directly. The result can be ventricular fibrillation. Lengthening the pathway’s refractory period is what procainamide and ibutilide do, and it is the only protection a drug can give.' }),
          multi('fbi', 'Unknown: fast, broad, irregular', sick ? 'A 27-year-old is brought in drowsy and sweating, blood pressure 68/40 mmHg, with a pulse too fast to count. The 12-lead is below.' : 'A 23-year-old collapsed at a party. He is now awake and light-headed, blood pressure 104/62 mmHg. The 12-lead is below.', [
            ['What is the rhythm?', 'Pre-excited atrial fibrillation', ['Monomorphic ventricular tachycardia', 'Atrial fibrillation with left bundle branch block', 'Torsades de pointes'], 'Irregularity excludes monomorphic VT. A QRS that changes width from beat to beat excludes a fixed bundle branch block. A constant axis with no twisting about the baseline, and a rate above 200/min, separate it from polymorphic VT.'],
            ['Which drugs are dangerous here?', 'Those that block the AV node', ['Those that block sodium channels', 'Those that prolong repolarisation', 'Those used for procedural sedation'], 'Adenosine, verapamil, diltiazem, digoxin, beta-blockers, and IV amiodarone given acutely (its early effects are nodal block and vasodilatation, and ventricular fibrillation is reported). They leave the pathway untouched, or faster.'],
            sick ? ['Treatment?', 'Synchronised cardioversion now', ['Procainamide infusion over 20 minutes', 'Amiodarone 300 mg IV over 20 minutes', 'An unsynchronised shock at low energy'], 'Unstable because of the rhythm: electricity, synchronised because there is a QRS and a pulse. Cardioversion is also the answer whenever there is doubt about the diagnosis or the drug.']
              : ['Treatment?', 'Procainamide or ibutilide IV, or cardioversion', ['Amiodarone 300 mg IV over 20 minutes', 'Diltiazem IV, then a beta-blocker', 'Adenosine 6 mg, then 12 mg'], 'Stable: a drug that acts on the pathway. Procainamide and ibutilide lengthen its refractory period, slow the pre-excited rate and often restore sinus rhythm. Synchronised cardioversion is always acceptable and is used at once if the patient deteriorates. Afterwards: ablation of the pathway.'],
          ], { bench: sheet(() => record(WPWAF(fbiErp, false, sd), { warm: 1000 })), tDone: 'Pre-excited atrial fibrillation', why: 'Irregular, wide and very fast with a changing QRS width: pre-excited AF. No AV-nodal blockers; procainamide or ibutilide if stable, cardioversion if not.' }),
        ];
      } },

    { id: 'm4', title: 'Regular wide-complex tachycardia', short: 'Wide-complex tachycardia', goal: 'Treat a regular wide-complex tachycardia as VT, choose between the drugs and a shock, and know the exceptions.',
      teach: () => [
        para('A regular wide-complex tachycardia is **ventricular tachycardia until proved otherwise**. The reasoning has two parts: the odds, and what a mistake costs.'),
        list(['**The odds.** About four in five are VT. With a previous infarct or any structural heart disease it is well over nine in ten. Age, blood pressure and how well the patient looks do not discriminate: VT is often tolerated for hours.',
          '**The mistakes are not symmetrical.** Treating SVT with aberrancy as VT (procainamide, amiodarone, cardioversion) works or does no harm. Treating VT as SVT with verapamil or diltiazem vasodilates and depresses contractility while the tachycardia continues: hypotension, ventricular fibrillation.',
          '**Unstable:** synchronised cardioversion. Pulseless: defibrillation and CPR.',
          '**Stable monomorphic VT: three drugs and their reasons.** **Procainamide** blocks sodium and potassium channels and slows conduction in the circuit until it fails; it terminated more VT than amiodarone, with fewer adverse events, in the one randomised comparison. Avoid it in severe heart failure, hypotension or a long QT. **Amiodarone** has little negative inotropy and is the usual choice with a poor ventricle; it is slower. **Lidocaine** binds inactivated sodium channels, so it acts mainly on depolarised, ischaemic tissue: second line, most useful in acute ischaemia.',
          '**Elective synchronised cardioversion under sedation** is the most reliable treatment of all and is appropriate at any point, including first. Drugs that have failed are not stacked.',
          '**Adenosine as a test.** In a stable patient with a regular, monomorphic wide-complex tachycardia, guidelines permit adenosine: it is gone in seconds, so it is safe even in VT. Termination means a node-dependent circuit (or, rarely, an adenosine-sensitive VT); AV block with continuing atrial activity means an atrial rhythm; no change means VT. Never for an irregular or polymorphic tachycardia.',
          '**The idiopathic exceptions**, in structurally normal hearts. **Fascicular VT** (right bundle branch block pattern, left axis, QRS only 120–140 ms) re-enters through calcium-channel-dependent Purkinje tissue and stops with verapamil. **Outflow-tract VT** (left bundle branch block pattern, inferior axis) is triggered activity that depends on cyclic AMP and stops with adenosine, vagal manoeuvres or a beta-blocker. These drugs are for a diagnosis that is already secure, never for an undiagnosed wide-complex tachycardia.'])],
      steps: () => {
        const cl = pick([320, 333, 345, 360]), rate = Math.round(60000 / cl);
        const VTB = sheet(() => record(VT(cl), { warm: 2000 })), VTL = Object.assign({}, VTB, { ladder: true });
        const who = pick(['A 66-year-old with an inferior infarct four years ago and an ejection fraction of 35 %', 'A 71-year-old who had bypass surgery after an inferior infarct nine years ago', 'A 58-year-old with a dilated cardiomyopathy and an ejection fraction of 35 %']);
        const dr = pick([
          { who: 'A 63-year-old with an inferior infarct six years ago has had palpitations for 40 minutes. Ejection fraction 45 %, no heart failure, blood pressure 124/76 mmHg, and a normal QT on his last ECG.',
            part: ['You choose a drug. Which has the best evidence for stopping this?', 'Procainamide', ['Amiodarone', 'Lidocaine', 'Magnesium sulfate'], 'Procainamide slows conduction in the circuit until it fails. In the one randomised comparison (PROCAMIO) it terminated more tachycardias than amiodarone with fewer major adverse events. Typical: 10 mg/kg over about 20 minutes, or 20–50 mg/min up to about 17 mg/kg, stopping for hypotension or marked QRS widening. It is avoided in severe heart failure, hypotension and a long QT.'] },
          { who: 'A 69-year-old with an ejection fraction of 20 % was admitted yesterday with decompensated heart failure and now has palpitations. Blood pressure 98/60 mmHg, alert, basal crackles.',
            part: ['You choose a drug. Which suits this ventricle?', 'Amiodarone', ['Procainamide', 'Flecainide', 'Sotalol'], 'Procainamide is a negative inotrope and vasodilator and is avoided in severe heart failure, as are flecainide and sotalol. Amiodarone has little negative inotropy and is the usual choice with a poor ventricle, although it is slower and stops fewer tachycardias. Typical: 150 mg over 10 minutes in North American practice, 300 mg over 10–60 minutes in UK and European practice, then an infusion.'] }]);
        const q0 = pick([130, 140, 150, 160]);
        const tv = pick([WCT.vt, WCT.svt, WCT.fl]), tcl = pick([333, 345, 360]), trate = tv.id === 'vt' ? Math.round(60000 / tcl) : tv.id === 'svt' ? 176 : 145;
        const TST = (rx, ctl) => strip((p) => wctRec(tv, tcl, p.rx), { wide: true, p: { rx }, ctl: ctl ? [{ k: 'rx', label: 'Give', opts: [['none', 'Nothing yet'], ['ver', 'Verapamil 5 mg IV over 2 minutes'], ['aden', 'Adenosine 6 mg, rapid bolus and flush']] }] : [] });
        const read = {
          vt: [['What did adenosine do?', 'Nothing: the tachycardia ran on unchanged', ['Stopped it: a pause, then sinus rhythm', 'Paused the ventricles and exposed flutter waves', 'Slowed it gradually, and then it sped up once more'], 'The cycle length is the same before, during and after the drug. For a few seconds the AV node conducted in neither direction, and the tachycardia did not notice.'],
            ['What does that mean?', 'It does not need the AV node: treat as VT', ['The dose was too small: repeat until it stops', 'It is sinus tachycardia with a bundle branch block', 'It is AVNRT with aberrancy'], 'A node-dependent circuit would have stopped, and an atrial rhythm would have shown its atrial activity during a ventricular pause. A regular wide-complex tachycardia that ignores adenosine is managed as VT.'],
            ['Next?', 'Procainamide or amiodarone, or cardioversion', ['Verapamil IV, as a longer-acting test', 'Adenosine again, at 12 mg and then 18 mg', 'A beta-blocker and a period of observation'], 'Stable VT: an antiarrhythmic drug chosen by the state of the ventricle, or synchronised cardioversion under sedation, which is always appropriate.']],
          svt: [['What did adenosine do?', 'Stopped it: a pause, then sinus rhythm', ['Nothing: the tachycardia ran on unchanged', 'Paused the ventricles and exposed flutter waves', 'Slowed it gradually, and then it sped up once more'], 'The tachycardia ends abruptly, sinus P waves appear, and conduction returns as the node recovers.'],
            ['What does that mean?', 'The AV node was part of the circuit', ['It was VT: adenosine stops most VT', 'It was atrial flutter with a wide QRS', 'Nothing: tachycardias often stop by chance'], 'Termination by a few seconds of nodal block means a node-dependent circuit. The sinus beats have the same wide QRS, so the bundle branch block was there all along: a supraventricular tachycardia with a wide QRS. One caveat: a few idiopathic outflow-tract VTs also stop with adenosine, so read the 12-lead in sinus rhythm.'],
            ['Next?', 'Manage as SVT; record a 12-lead in sinus rhythm', ['Load with amiodarone for 24 hours', 'Refer for an implantable defibrillator now', 'Start a procainamide infusion'], 'If it returns, adenosine again or a longer-acting AV-nodal blocker, now that the diagnosis is made. The sinus 12-lead documents the bundle branch block and excludes pre-excitation.']],
          fl: [['What did adenosine do?', 'Paused the ventricles and exposed flutter waves', ['Stopped it: a pause, then sinus rhythm', 'Nothing: the tachycardia ran on unchanged', 'Slowed it gradually, and then it sped up once more'], 'For a few seconds there are no QRS complexes, and a continuous sawtooth at about 290/min is visible. Then the same tachycardia resumes.'],
            ['What does that mean?', 'An atrial rhythm with a bundle branch block', ['Ventricular tachycardia with retrograde conduction', 'AVNRT conducted with a bundle branch block', 'Pre-excited atrial fibrillation'], 'The atria continue regardless of the node: atrial flutter, conducted 2:1 with a wide QRS because of a bundle branch block.'],
            ['Next?', 'Rate control or cardioversion, and anticoagulation', ['Procainamide infusion, as for ventricular tachycardia', 'Adenosine again until the flutter stops', 'An unsynchronised shock at maximum energy'], 'Flutter is managed as in the previous unit. More adenosine will only show the same thing again.']] };
        const idio = pick([
          { bench: sheet(() => record(lib('vt-fasc'), { warm: 2000 })), who: 'A 24-year-old athlete with a normal echocardiogram has had two identical episodes; the last was studied in the electrophysiology laboratory. He is stable. The 12-lead is below.',
            what: ['Which recognised entity is this?', 'Fascicular VT', ['Outflow-tract VT', 'Scar-related VT', 'Bundle branch re-entry'], 'A right bundle branch block pattern with left axis deviation and a QRS of only about 133 ms, in a young person with a normal heart: re-entry involving the left posterior fascicle.'],
            drug: ['Which drug terminates it?', 'Verapamil', ['Adenosine', 'Lidocaine', 'Digoxin'], 'The circuit includes slowly conducting, calcium-channel-dependent Purkinje tissue. IV verapamil terminates it; adenosine and vagal manoeuvres usually do not.'] },
          { bench: sheet(() => record(RVOT(), { warm: 3000 })), who: 'A 31-year-old with a normal echocardiogram and a normal cardiac MRI gets this tachycardia on exertion; it has been documented before. She is stable. The 12-lead is below.',
            what: ['Which recognised entity is this?', 'Outflow-tract VT', ['Fascicular VT', 'Scar-related VT', 'Bundle branch re-entry'], 'A left bundle branch block pattern with tall R waves in II, III and aVF: an origin high in the outflow tract, in a normal heart.'],
            drug: ['Which drug terminates it?', 'Adenosine', ['Digoxin', 'Lidocaine', 'Atropine'], 'This is triggered activity from delayed after-depolarisations that depend on cyclic AMP. Adenosine, vagal manoeuvres, beta-blockers and verapamil all lower it and can stop the tachycardia.'] }]);
        return [
          look('What proves it, when it is there', 'Regular, wide (QRS about 147 ms) and ' + rate + '/min. The ladder diagram under the rhythm strip shows what is hard to see at this rate: the atria keep their own slower time, about 79/min, and none of their impulses is related to the QRS complexes. That is AV dissociation; on the tracing the P waves are only small notches that deform an occasional T wave. Easier to see are the one or two beats that are narrow and different: a sinus impulse has found the ventricle recovered and captured it. Either sign proves VT. Their absence proves nothing, which is why the next step is about odds and not criteria.', VTL),
          mcq('prior', 'The odds', who + ' has this regular wide-complex tachycardia. He is comfortable, with a blood pressure of 118/72 mmHg, and has had it for half an hour. Before any ECG criteria are applied, how likely is ventricular tachycardia?',
            ['More than nine in ten', 'About one in two', 'About one in five: he is stable', 'Unknowable without adenosine'],
            'Four in five regular wide-complex tachycardias are VT in unselected patients; with a previous infarct or structural heart disease it is well over nine in ten. Blood pressure, age and how well the patient looks do not discriminate: VT in a scarred ventricle is often tolerated for hours. Start from VT and ask what would change your mind.', { bench: VTB, keep: true }),
          multi('vt-stable', 'A stable patient', dr.who + ' The 12-lead is below.', [
            ['Working diagnosis?', 'Ventricular tachycardia', ['SVT with aberrancy, because he is stable', 'Antidromic AVRT, because it is regular', 'Sinus tachycardia with a bundle branch block'], 'A regular wide-complex tachycardia in a patient with structural heart disease. Stability is not evidence against VT.'],
            ['A colleague suggests verapamil "in case it is SVT". What would it do in VT?', 'Drop the pressure and leave the VT running', ['Terminate it in about half of patients', 'Slow it enough to show the P waves', 'Nothing: ventricular muscle ignores it'], 'Verapamil vasodilates and depresses contractility. Scar-related VT does not depend on calcium-channel tissue, so the tachycardia continues in a ventricle that can no longer cope: hypotension, ventricular fibrillation. Treating SVT as VT is safe; treating VT as SVT is not.'],
            dr.part,
            ['Twenty minutes later the tachycardia continues and he is unchanged. Next?', 'Synchronised cardioversion under sedation', ['A second antiarrhythmic drug on top', 'An unsynchronised shock at maximum energy', 'Wait: stable VT stops by itself'], 'Cardioversion is the most reliable treatment and is appropriate at any point, including first. Stacking antiarrhythmic drugs adds hypotension and proarrhythmia. He has a pulse and a QRS, so the shock is synchronised.'],
          ], { bench: VTB, keep: true, tDone: 'Stable VT: the drug, and when to stop trying drugs', why: 'A regular wide-complex tachycardia with structural heart disease is VT. Never verapamil; procainamide or amiodarone by the state of the ventricle; cardioversion if the drug fails.' }),
          num('procainamide-stop', 'When to stop the infusion', 'Procainamide is running. Before it started, the QRS during tachycardia measured ' + q0 + ' ms. One of the stopping rules is widening of the QRS by more than half. At what QRS duration do you stop?', 1.5 * q0, 8, 'ms',
            1.5 * q0 + ' ms. Procainamide slows conduction: that is how it stops the circuit, and the QRS width is the visible measure of how much sodium-channel block is on board. The infusion stops when the arrhythmia stops, the pressure falls, the QRS has widened by 50 %, or the maximum dose has been given.'),
          mcq('lido-why', 'Why lidocaine prefers ischaemia', 'Lidocaine is weak against VT from an old scar and more useful against VT in acute ischaemia. Why?',
            ['It binds inactivated sodium channels, common in depolarised ischaemic cells', 'It blocks potassium channels, which open only in ischaemic myocardium', 'It dilates the coronary arteries and relieves the ischaemia directly', 'It blocks calcium entry, which drives the after-depolarisations of ischaemia'],
            'Class Ib drugs bind sodium channels in the inactivated state and let go quickly. Cells at a normal resting potential are barely affected. Ischaemic cells are partly depolarised, their channels spend longer inactivated, and the block accumulates there. Typical 1–1.5 mg/kg. It is second line for stable VT, and the alternative to amiodarone in ventricular fibrillation.'),
          mcq('aden-which', 'Adenosine as a test', 'Guidelines permit adenosine as a test in some wide-complex tachycardias. Which?',
            ['Regular and monomorphic, in a stable patient', 'Irregular, with a QRS that keeps changing in width', 'Polymorphic, with a long QT in sinus rhythm', 'Any of them, provided the pressure is low'],
            'Regular and monomorphic means VT, or a node-dependent or atrial tachycardia with a wide QRS; adenosine separates them without lasting harm because it is gone in seconds. Irregular and wide may be pre-excited atrial fibrillation, where blocking the node is dangerous. Polymorphic VT is never an adenosine question, and an unstable patient is cardioverted.'),
          act('wct-test', 'The permitted test', 'A ' + pick([38, 47, 52]) + '-year-old with no records has a regular, monomorphic wide-complex tachycardia at ' + trate + '/min. Stable, blood pressure 122/76 mmHg, and the 12-lead does not settle the diagnosis. One of the drugs on the bench is a permitted test. Give it.', { bench: TST('none', true),
            check: (x, st) => { if (x.p.rx === 'ver') st.bad = true; return x.p.rx === 'aden' && (!st.bad || !!x.p.shown); }, solve: (b) => { b.p.shown = 1; b.set('rx', 'aden'); },
            live: (x, st) => (x.p.shown ? null : x.p.rx === 'ver' || st.bad ? (x.rec.x.rx !== 'ver' ? 'Verapamil had already been given. Use "Show me" to see the test that should have been chosen.' : x.rec.x.vf ? 'Verapamil: the pressure fell, the tachycardia continued, and it has degenerated into ventricular fibrillation. This was VT. Use "Show me" to see the test that should have been chosen.' : 'It changed the rhythm, and this patient was lucky: had it been VT, the same injection would have caused collapse. Verapamil is not a test. Use "Show me" to see the one that is.') : null),
            hint: 'Which of the two is gone in seconds if you are wrong?',
            why: 'Adenosine: a few seconds of AV-nodal block, and then it is gone. Whatever the rhythm, the patient is no worse and the strip now carries information. Verapamil lasts for hours and, if the rhythm is VT, causes collapse: it is never used to find out.' }),
          multi('wct-read', 'Read the test', 'A stable patient with a regular wide-complex tachycardia at ' + trate + '/min, of uncertain origin, has been given adenosine. The strip shows the response.', read[tv.id], { bench: TST('aden', false), tDone: 'Adenosine in a wide-complex tachycardia: reading the result', why: 'Termination: the node was in the circuit. A pause with atrial activity: an atrial rhythm. No change: treat as VT.' }),
          multi('idiopathic', 'The exceptions', idio.who, [idio.what, idio.drug,
            ['A registrar proposes the same drug for the next wide-complex tachycardia, in a 67-year-old with an old infarct. Your answer?', 'No: only when idiopathic VT is an established diagnosis', ['Yes: it is safe if the blood pressure is normal', 'Yes: it is diagnostic as well as therapeutic', 'Yes: but at half the dose and more slowly'], 'These drugs are for a diagnosis that is already secure: a known normal heart, the typical 12-lead, usually a previous documented episode. In an undiagnosed wide-complex tachycardia the odds are scar-related VT, in which verapamil causes collapse and adenosine does nothing.'],
          ], { bench: idio.bench, tDone: 'Idiopathic VT: the verapamil- and adenosine-sensitive exceptions', why: 'Fascicular VT stops with verapamil and outflow-tract VT with adenosine, but only when that diagnosis is already secure.' }),
        ];
      } },

    { id: 'm5', title: 'Polymorphic VT, torsades de pointes, VF and electrical storm', short: 'Polymorphic VT and storm', goal: 'Branch on the QT in sinus rhythm, treat torsades and ischaemic polymorphic VT in their opposite ways, and break an electrical storm.',
      teach: () => [
        para('Polymorphic VT is not one disease. **The branch point is the QT interval of the sinus beats before the run**, because the two branches have opposite treatments.'),
        list(['**Long QT: torsades de pointes.** Prolonged repolarisation allows early after-depolarisations, and a pause makes the next QT longer still (short–long–short onset). Treat the repolarisation: **magnesium sulfate 2 g IV**, which suppresses the after-depolarisations even with a normal magnesium level and does not shorten the QT; a **faster heart rate** (typically 90–110/min by temporary pacing, or isoprenaline), which shortens the QT and removes pauses; **potassium** to 4.5–5.0 mmol/L; and **stopping every QT-prolonging drug**. A sustained run is defibrillated.',
          '**What makes torsades worse:** antiarrhythmics that prolong the QT (amiodarone, sotalol, procainamide) and, in acquired long QT, anything that slows the rate. Congenital long QT is different: there adrenergic stimulation is usually the trigger, beta-blockers are the treatment and isoprenaline is avoided.',
          '**Normal QT: ischaemia until proved otherwise.** Urgent angiography and revascularisation, a beta-blocker, and amiodarone (or lidocaine). Magnesium and pacing are not expected to help. Two named exceptions with a normal QT and no ischaemia: **catecholaminergic polymorphic VT** (young, on exertion or emotion, often bidirectional; beta-blocker and sedation, and catecholamines make it worse) and **Brugada syndrome** (coved ST elevation in V1–V2, events at rest or with fever; isoprenaline or quinidine for repeated events, treat fever, avoid sodium-channel blockers).',
          '**Ventricular fibrillation and pulseless VT:** CPR and defibrillation at once; after every shock CPR resumes immediately for two minutes before the rhythm is checked. Adrenaline 1 mg is given every 3–5 minutes, starting after the second or the third shock depending on the algorithm; amiodarone 300 mg (or lidocaine) after the third. Only the shock terminates fibrillation. Then look for the cause, coronary occlusion above all.',
          '**Electrical storm** is three or more separate episodes of sustained VT or VF, or appropriate ICD therapies, within 24 hours. Pain and fear from each shock raise sympathetic drive, which brings the next episode. Break the loop: **beta-blockade** (non-selective propranolol did better than metoprolol in one trial), **amiodarone**, **sedation** as deep as it needs to be, **reprogramming the ICD** (longer detection, more antitachycardia pacing, fewer shocks), **treating the trigger** (ischaemia, potassium, magnesium, heart failure, a new drug) and early **catheter ablation** for recurrent monomorphic VT.',
          'The drug for a storm still depends on the ECG between episodes: polymorphic VT with a long QT gets the torsades regimen, not amiodarone.'])],
      steps: () => {
        const crit = pick([500, 480, 465]);
        const T0 = strip(() => torsades(crit, 0), { wide: true, strips: [1, 6], read: tdpRead });
        const long = pick([true, false]);
        const isch = () => { const rec = record(lib('pmvt'), { dur: 12000 }), q = seen(rec, 'QRS').filter((e) => e.label === 'conducted'); rec.x = { qt: Math.round(q[1].wave.qt), rate: Math.round(60000 / q[1].rr) }; return rec; }, nq = once('isch', () => isch().x);
        const QB = long ? T0 : strip(isch, { wide: true, strips: [1, 6], read: (rec) => [['Sinus rate', rec.x.rate, '/min'], ['QT of a sinus beat', rec.x.qt, 'ms']] });
        const PB = strip((p) => torsades(crit, p.pace), { wide: true, strips: [1, 6], p: { pace: 0 }, markers: true, ctl: [{ k: 'pace', label: 'Atrial pacing rate (0 = off)', min: 0, max: 120, step: 10, unit: '/min' }], read: tdpRead });
        const storm = strip(() => record(VT(315), { warm: 1500, dur: 12000, script: [{ t: 4300, do: (s, t) => s.shock(t, { j: 35 }) }, { t: 8200, do: (s, t) => { const f = s.focus('vt'); f.enabled = true; f.arm(t); } }, { t: 11600, do: (s, t) => s.shock(t, { j: 35 }) }] }), { wide: true, cap: 'Telemetry: two of the seven episodes' });
        const branch = long ? [
          ['What is the QT before the run, and so the diagnosis?', 'Long: torsades de pointes', ['Normal: ischaemic polymorphic VT', 'Long: monomorphic VT with aberrancy', 'Normal: pre-excited atrial fibrillation'], 'A QT above 600 ms at 52/min (QTc about 585 ms), three QT-prolonging influences, and a short–long–short onset: torsades de pointes.'],
          ['Treatment between runs?', 'Magnesium 2 g IV, potassium, and stop the drugs', ['Amiodarone 300 mg IV over 20 minutes, then an infusion', 'A procainamide infusion', 'Metoprolol IV in 5 mg boluses'], 'Magnesium suppresses the early after-depolarisations that trigger each run, even when the serum level is normal, and it does not shorten the QT. Potassium is taken to the upper normal range and every QT-prolonging drug is stopped. A sustained run is defibrillated.'],
          ['A colleague draws up amiodarone "for the VT". What would it do here?', 'Lengthen the QT and invite the next run', ['Shorten the QT within a few minutes', 'Stop the runs but lower the pressure', 'Nothing: it does not affect repolarisation'], 'Amiodarone, sotalol and procainamide all prolong repolarisation. The reflex "wide-complex tachycardia, so amiodarone" is wrong when the QT in sinus rhythm is long.']]
          : [['What is the QT before the run, and so the diagnosis?', 'Normal: ischaemic polymorphic VT', ['Long: torsades de pointes', 'Long: monomorphic VT with aberrancy', 'Normal: pre-excited atrial fibrillation'], 'A QT of about ' + nq.qt + ' ms at ' + nq.rate + '/min is normal (QTc about ' + Math.round(nq.qt / Math.sqrt(60 / nq.rate) / 10) * 10 + ' ms). Polymorphic VT with a normal QT, in a patient with chest pain and ST depression, is ischaemia until proved otherwise.'],
            ['Treatment between runs?', 'Urgent angiography, a beta-blocker, amiodarone', ['Magnesium, potassium and overdrive pacing at 100/min', 'An isoprenaline infusion', 'A procainamide infusion'], 'The definitive treatment is revascularisation; a beta-blocker and amiodarone (or lidocaine) hold the rhythm until then. Isoprenaline would raise oxygen demand in an ischaemic ventricle.'],
            ['Why are magnesium and pacing not the answer here?', 'They treat long-QT triggers, which are absent', ['They work only in monomorphic VT', 'They are contraindicated in infarction', 'They need a potassium above 5 mmol/L'], 'Magnesium and a faster rate act on early after-depolarisations and pause-dependence, the mechanism of torsades. Ischaemic polymorphic VT is re-entry in injured muscle with a normal QT. Magnesium does little harm, but it must not delay the angiogram.']];
        return [
          look('Start with the sinus beats', 'Look at the sinus beats first, not the tachycardia. The QT is very long: over 600 ms at 52/min, with a broad, late T wave. Then follow the sequence: an extrasystole, a pause, a sinus beat whose QT is longer still, and a second extrasystole on that T wave, which starts a polymorphic tachycardia with peaks that swing around the baseline. Short, long, short. It stops by itself, and it will come back.', T0),
          num('qt-measure', 'The branch point', 'A patient with runs of polymorphic VT. Before anything else: measure the QT interval of one of the first sinus beats on the strip, from the start of the QRS to the end of the T wave.', (b) => b.rec.x.qt, 40, 'ms',
            (b) => 'About ' + b.rec.x.qt + ' ms at ' + b.rec.x.rate + '/min. ' + (long ? 'That is long by any correction (QTc about 585 ms). ' : 'That is normal (QTc about ' + Math.round(b.rec.x.qt / Math.sqrt(60 / b.rec.x.rate) / 10) * 10 + ' ms). ') + 'The measurement is made on sinus beats before the run, never during it, and it decides which of two opposite treatments the patient gets.', { bench: QB }),
          multi('pvt-branch', 'Long QT or normal QT', long ? 'She is 68, on sotalol, was started on clarithromycin three days ago and has had diarrhoea. Potassium 3.0 mmol/L. Three brief blackouts this morning.' : 'He is 57 and has had central chest pain for 40 minutes, with ST depression in the lateral leads. Two brief blackouts in the department.', branch,
            { bench: QB, keep: true, tDone: long ? 'Polymorphic VT with a long QT: torsades' : 'Polymorphic VT with a normal QT: ischaemia', why: 'The QT of the sinus beats decides: long means torsades (magnesium, rate, potassium, stop the drug); normal means ischaemia (revascularise, beta-blocker, amiodarone).' }),
          mcq('pace-predict', 'Predict: a faster rate', 'A patient with acquired long QT: magnesium has been given twice and potassium is running, but the runs continue. You are about to pace the atrium faster than the sinus rate of 52/min. What should that do?',
            ['Shorten the QT and abolish the pauses, so the triggers stop', 'Suppress the triggers by overdrive, with the QT unchanged', 'Lengthen the QT, but capture the ventricle before each trigger', 'Nothing, unless the ventricle is paced as well'],
            'The QT shortens as the cycle shortens, and a paced rhythm has no pauses. Both act on the mechanism: early after-depolarisations grow with a long action potential and are largest after a long cycle.', { bench: PB }),
          act('pace-rate', 'Pace until the runs stop', 'Acquired long QT with recurrent torsades despite magnesium; the sinus rate is 52/min. Pace the atrium, and find a rate at which the strip stays clear of torsades.', { bench: PB, keep: true,
            check: (x) => x.p.pace > 0 && x.rec.x.paced && !x.rec.x.tdp, solve: (b) => b.set('pace', 110),
            live: (x) => (x.p.pace > 0 && !x.rec.x.paced ? x.p.pace + '/min is below the sinus rate: the pacemaker is inhibited and nothing has changed.' : x.p.pace > 0 && x.rec.x.tdp ? 'Paced at ' + x.p.pace + '/min: the QT is ' + x.rec.x.qt + ' ms and the runs continue.' : null), hint: 'Typical rates for this are well above a normal resting rate.',
            why: (b) => 'At ' + b.p.pace + '/min the QT has shortened from about 627 ms to ' + b.rec.x.qt + ' ms and there are no pauses, so the triggers have stopped. Typical rates are 90–110/min, occasionally higher, through a temporary atrial or ventricular wire. Pacing covers the next hours; the cure is the potassium and stopping the drug.' }),
          mcq('iso-when', 'No wire for half an hour', 'No pacing wire can be placed for half an hour. Which infusion does the same job, and when is it avoided?',
            ['Isoprenaline; not in congenital long QT or active ischaemia', 'Amiodarone; not in thyroid disease or pulmonary fibrosis', 'Esmolol; not in asthma or decompensated heart failure', 'Verapamil; not in heart failure or with a beta-blocker'],
            'Isoprenaline raises the sinus rate, which shortens the QT and removes pauses: a chemical pacemaker for acquired, pause-dependent torsades. In most congenital long-QT syndromes adrenergic stimulation is the trigger, so it is avoided there; and it raises myocardial oxygen demand, so it is not used in ischaemia.'),
          num('cpr-min', 'After the shock', 'A run does not stop: the patient is pulseless in ventricular fibrillation and is defibrillated. After the shock, chest compressions restart at once, without a pulse check. For how many minutes before the rhythm is looked at again?', 2, 0.01, 'minutes',
            'Two minutes. Even a successful shock is followed by a period of poor output, and compressions do no harm to a heart that has restarted. Every interruption costs coronary perfusion pressure. The cycle is: shock, two minutes of CPR, rhythm check.'),
          mcq('vf-drugs', 'After the third shock', 'Ventricular fibrillation persists after the third shock. Which drug and dose do both major resuscitation algorithms place here?',
            ['Amiodarone 300 mg IV bolus', 'Amiodarone 150 mg over 10 minutes', 'Magnesium 2 g IV bolus', 'Procainamide 10 mg/kg over 20 minutes'],
            'Amiodarone 300 mg (lidocaine is the alternative), with a further 150 mg later if fibrillation persists. The 150 mg over 10 minutes is a dose for VT with a pulse. Adrenaline 1 mg is given every 3–5 minutes, starting after the second shock in the American algorithm and after the third in the European one. Magnesium is for torsades. None of these terminates fibrillation: the shock does.'),
          multi('storm', 'Seven shocks in three hours', 'A 64-year-old with an old infarct (ejection fraction 25 %) and an ICD has had seven shocks in three hours. He is awake, terrified and tachycardic between episodes; blood pressure 104/60 mmHg, potassium 3.3 mmol/L. The strip shows what keeps happening.', [
            ['Why does each shock make the next episode more likely?', 'Pain and fear raise sympathetic drive, which triggers VT', ['Each shock lengthens the QT interval a little more', 'Each shock raises the serum potassium a little more', 'The battery weakens, and bradycardia pacing fails'], 'Electrical storm (three or more separate episodes within 24 hours) is sustained by adrenergic drive. A shock while conscious is among the most frightening experiences in medicine, and the catecholamine surge lowers the threshold for the next episode.'],
            ['First measures?', 'A beta-blocker, amiodarone and sedation', ['Lidocaine alone, with reassurance', 'An adrenaline infusion for the pressure', 'Verapamil IV, followed by digoxin'], 'Block the sympathetic limb: a beta-blocker (non-selective propranolol did better than metoprolol in one randomised trial) with amiodarone, and sedation as deep as it needs to be, up to general anaesthesia. Correct potassium and magnesium, and look for the trigger: ischaemia, decompensated heart failure, a new drug, fever.'],
            ['And the device?', 'Reprogram it: longer detection, fewer shocks', ['Leave it alone: it is doing its job', 'Raise every shock to maximum energy, to be sure', 'Replace the generator this week'], 'The ICD is treating appropriately and adding to the problem. Longer detection lets self-terminating runs stop, and antitachycardia pacing ends many monomorphic VTs painlessly.'],
            ['The VT keeps returning despite all this. Next?', 'Urgent catheter ablation', ['A third antiarrhythmic drug', 'Removal of the ICD', 'Discharge with a monitor'], 'Recurrent monomorphic VT in a scarred ventricle has a circuit that can be mapped and ablated, and ablation is recommended for a storm that drugs do not control. Sympathetic blockade can be deepened (stellate ganglion block) and mechanical support used as a bridge.'],
          ], { bench: storm, tDone: 'Electrical storm: break the sympathetic loop', why: 'Storm is driven by sympathetic tone: beta-blocker, amiodarone, sedation, reprogram the ICD, treat the trigger, ablate.' }),
        ];
      } },

    { id: 'm6', title: 'Bradycardia and AV block', short: 'Bradycardia', goal: 'Find the level of block, predict what atropine will do, and bridge to pacing.',
      teach: () => [
        para('A slow heart rate is treated only when it is **causing** something: syncope, hypotension and poor perfusion, heart failure, ischaemia, or pause-dependent ventricular arrhythmia. Then two questions decide the rest: **is there a reversible cause, and where is the block?**'),
        list(['**Reversible causes first:** drugs that slow the node (beta-blockers, verapamil, diltiazem, digoxin, amiodarone), hyperkalaemia, inferior myocardial infarction, hypothyroidism, hypothermia, and raised intracranial pressure (bradycardia with hypertension).',
          '**The level of block.** In the **AV node** conduction is decremental and under vagal control: the block is usually Wenckebach, the QRS narrow, and the escape rhythm junctional at 40–60/min and dependable. **Below the node**, in the His–Purkinje system, conduction is all-or-none: Mobitz II, a wide QRS, and a ventricular escape at 20–40/min that can stop without warning.',
          '**Atropine** blocks muscarinic receptors: it speeds the sinus node and improves conduction through the AV node. Typical 0.5–1 mg IV, repeated every few minutes to a total of 3 mg. It helps sinus bradycardia and nodal block. It does nothing for the His–Purkinje system, and in infranodal block the faster atrial rate presents more impulses to tissue that cannot conduct them: the block, and the ventricular rate, can get worse. In a transplanted, denervated heart it has no useful effect.',
          '**Catecholamine infusions are bridges:** isoprenaline, adrenaline (typically 2–10 µg/min) or dopamine (typically 5–20 µg/kg/min). They speed the sinus node, the AV node and escape pacemakers below a block. Isoprenaline vasodilates and raises oxygen demand, so it is avoided in ischaemia.',
          '**Pacing:** transcutaneous at once for the unstable patient, with analgesia and proof that each stimulus produces a pulse; then a transvenous wire; then the decision about a permanent system.',
          '**Who needs a permanent pacemaker, in outline:** acquired Mobitz II, high-grade and complete AV block that is not due to a reversible or transient cause, with or without symptoms; and sinus node disease when symptoms are clearly due to the bradycardia. Not asymptomatic sinus bradycardia, first-degree block, or Wenckebach in sleep or in athletes.',
          '**Infarction.** AV block with an inferior infarct is usually nodal, narrow, responsive to atropine and gone within days. With an anterior infarct it means necrosis of the septum and bundle branches: infranodal, and it needs pacing.'])],
      steps: () => {
        const lv = pick(['nodal', 'infra']), nodal = lv === 'nodal';
        const bi = once('block-' + lv, () => { const b = blockRec(lv, 'none'), a = blockRec(lv, 'atr'); return { qrs: b.x.qrs, pr: b.x.pr, a0: rates(b).aRate, v0: rates(b).vRate, a1: rates(a).aRate, ratio: a.x.ratio }; }), a0 = bi.a0, a1 = bi.a1;
        const B0 = strip(() => blockRec(lv, 'none'), { wide: true, read: blockRead });
        const BM = (man, ctl) => strip((p) => blockRec(lv, p.man), { wide: true, p: { man }, ctl: ctl ? MAN : [], read: blockRead });
        const who = nodal ? 'A 61-year-old, one day after an inferior infarct treated by angioplasty, has this 2:1 AV block on the monitor.' : 'A 78-year-old who has blacked out twice this week has this 2:1 AV block on the monitor.';
        const esc = pick([1700, 1820, 2000]), vr = once('chb-' + esc, () => perMin(seen(record(CHB(esc, true), { warm: 2000, dur: 12000 }), 'QRS')));
        const CB = (ctl) => strip((p) => record(CHB(esc, p.atr), { warm: 2000, dur: 12000 }), { wide: true, p: { atr: !ctl }, ctl: ctl ? [{ k: 'atr', label: 'Atropine 1 mg IV given', toggle: true }] : [], read: (rec, p, m) => [['Atrial rate', m.aRate, '/min'], ['Ventricular rate', m.vRate, '/min']] });
        const rev = pick([
          ['A 76-year-old on bisoprolol and verapamil has been vomiting for three days. Junctional rhythm at 34/min, blood pressure 82/48 mmHg, creatinine 310 µmol/L, potassium 6.8 mmol/L. What treats this bradycardia?',
            ['IV calcium, insulin with glucose, and stopping the drugs', 'Atropine to 3 mg, and then a permanent pacemaker', 'Transvenous pacing first: the potassium can wait', 'Amiodarone, to stabilise the junctional rhythm'],
            'Renal failure, hyperkalaemia and AV-nodal drugs potentiate one another. The bradycardia is a symptom of the potassium and of the drug levels. Calcium antagonises the membrane effect of potassium within minutes; insulin with glucose and salbutamol shift it into cells; fluids restore renal perfusion. Pacing often fails to capture until the potassium falls, and the reason for a permanent device disappears with the cause.'],
          ['A 45-year-old with a head injury is becoming drowsier. Sinus bradycardia at 42/min, blood pressure 208/112 mmHg, irregular breathing, and one pupil is dilating. What treats this bradycardia?',
            ['Lowering the intracranial pressure', 'Atropine 1 mg, repeated to a total of 3 mg', 'Transcutaneous pacing at 70/min', 'Labetalol, to bring the pressure down'],
            'Bradycardia with hypertension and irregular breathing is the Cushing response to raised intracranial pressure: the hypertension maintains cerebral perfusion and the bradycardia is the baroreflex answer to it. The heart is healthy. Treat the brain; pacing, or lowering the blood pressure, misses the point.']]);
        const ppm = shuffle(['Wenckebach block during sleep in a 26-year-old rower', 'A sinus rate of 44/min without symptoms in a 70-year-old', 'Complete block on day two of an inferior infarct, narrow escape', 'First-degree block with a PR of 240 ms and no symptoms']).slice(0, 3);
        const means = nodal ? [
          ['What did atropine do, and why?', 'Restored 1:1 conduction: the node recovers faster', ['Worsened the block: more impulses reached the node', 'Nothing: the degree of block is fixed', 'Sped up an escape rhythm below the block'], 'Vagal tone was prolonging the refractory period of the node. With it removed every impulse conducts, although the atrial rate has risen from ' + a0 + ' to ' + a1 + '/min.'],
          ['If this bradycardia causes symptoms, the first drug is…', 'Atropine, repeated to a total of 3 mg', ['Isoprenaline, through a central line only', 'Adenosine 6 mg by rapid bolus', 'Amiodarone 150 mg over 10 minutes'], 'Nodal block with a vagal component is where atropine works. Pacing is for the patient who stays symptomatic in spite of it.'],
          ['And a permanent pacemaker?', 'Usually not: this block resolves within days', ['Yes, today: any 2:1 block needs one', 'Yes, if atropine is needed more than once', 'Only if the QRS stays narrow for a week'], 'AV block in inferior infarction is at the node, from vagal reflexes and nodal ischaemia, and nearly always resolves within days. A permanent system is considered only if the block persists.']]
          : [['What did atropine do, and why?', 'Worsened it: more impulses than the tissue can conduct', ['Improved it: the node now recovers faster', 'Nothing: the degree of block is fixed whatever the atrial rate', 'Sped up an escape rhythm below the block'], 'Atropine sped the atria from ' + a0 + ' to ' + a1 + '/min and has no action on the His–Purkinje system. Conduction went from 2:1 to ' + bi.ratio + ' and the ventricular rate fell.'],
            ['Symptomatic bradycardia in this patient: the bridge is…', 'Pacing; isoprenaline or adrenaline meanwhile', ['Atropine, repeated every 3 minutes to a total of 3 mg', 'Atropine by continuous infusion', 'Glycopyrronium 0.4 mg IV'], 'A catecholamine can speed whatever pacemaker lies below the block while pacing is set up: transcutaneous first, then a transvenous wire. More anticholinergic drug is more of what failed.'],
            ['And a permanent pacemaker?', 'Yes, even if the symptoms settle', ['No: 2:1 block is a benign rhythm', 'Only if the escape rate is under 30/min', 'Only after a positive tilt test'], 'Acquired infranodal block is an indication for permanent pacing whether or not there are symptoms: the escape rhythm below it is slow and unreliable, and progression to complete block is unpredictable.']];
        return [
          look('Two P waves for every QRS', 'Count the P waves: there are two for every QRS, and every second one, sitting on or just after the T wave, is not followed by a QRS. This is 2:1 AV block. From one strip it cannot be called Mobitz I or Mobitz II, because there are never two conducted beats in a row to compare. What matters is where the block is, and the conducted beats carry two clues: the width of the QRS and the length of the PR interval.', B0),
          mcq('level-clue', 'Where is the block?', who + ' Conducted beats: QRS ' + bi.qrs + ' ms, PR ' + bi.pr + ' ms. Where is the block most likely to be?',
            nodal ? ['In the AV node', 'Below the node, in the His–Purkinje system', 'In the sinus node (sino-atrial exit block)', 'Nowhere: these are blocked atrial ectopic beats'] : ['Below the node, in the His–Purkinje system', 'In the AV node', 'In the sinus node (sino-atrial exit block)', 'Nowhere: these are blocked atrial ectopic beats'],
            nodal ? 'A narrow QRS means the His–Purkinje system is working, and a long PR on the conducted beats puts the delay in the node. The setting fits: inferior infarction brings vagal reflexes and an ischaemic node. Probable is not proven, and the next step tests it.' : 'A wide QRS (bundle branch and fascicular block) with a normal PR on the conducted beats: the node conducts promptly and the His–Purkinje system fails on every second beat. Syncope fits. Probable is not proven, and the next step tests it.', { bench: B0, keep: true }),
          act('level-test', 'Test the level at the bedside', who + ' One of the two manoeuvres on the bench will restore 1:1 conduction. Find it.', { bench: BM('none', true),
            check: (x) => x.p.man !== 'none' && x.rec.x.oneToOne, solve: (b) => b.set('man', nodal ? 'atr' : 'csm'),
            live: (x) => (x.p.man !== 'none' && !x.rec.x.oneToOne ? 'Atrial rate ' + x.m.aRate + '/min, ventricular rate ' + x.m.vRate + '/min, conduction ' + x.rec.x.ratio + '. The ventricular rate has fallen: worse, not better.' : null),
            hint: 'Atropine speeds the sinus node and the AV node. Carotid massage slows both. Neither acts on the His–Purkinje system.',
            why: nodal ? 'Atropine removed vagal tone: the refractory period of the node shortened, and every impulse conducted although the atrial rate rose. Carotid massage did the opposite. Block that improves with atropine or exercise and worsens with vagal manoeuvres is in the node.'
              : 'Carotid massage slowed the sinus node, and at the slower rate the diseased His–Purkinje system had time to recover between impulses: 1:1. Atropine sped the atria, and the block went from 2:1 to 3:1 with a slower ventricular rate. Block that worsens with atropine or exercise and improves when the atrial rate falls is below the node. Carotid massage is a test here, not a treatment.' }),
          multi('level-means', 'What the level means', 'This patient had 2:1 AV block with an atrial rate of ' + a0 + '/min and a ventricular rate of ' + bi.v0 + '/min. Atropine 1 mg has now been given, and the strip shows the result.', means, { bench: BM('atr', false), tDone: nodal ? 'Nodal block: atropine, and time' : 'Infranodal block: pace', why: 'Atropine improves nodal block and can worsen infranodal block. Infranodal block needs a pacemaker; nodal block from a reversible cause usually does not.' }),
          num('atropine-max', 'How much atropine', 'Atropine is given as boluses of 0.5–1 mg every few minutes. What is the typical maximum total dose?', 3, 0.01, 'mg',
            '3 mg, about 0.04 mg/kg: the dose that blocks the cardiac muscarinic receptors completely. More adds side effects and nothing else. If 3 mg has not worked the problem is not vagal, and the next step is pacing or a catecholamine infusion.'),
          num('chb-atropine', 'Atropine below the node', 'An 81-year-old is drowsy and cold, with a blood pressure of 74/40 mmHg. Give atropine on the bench. What is the ventricular rate afterwards?', vr, 4, '/min',
            'Still about ' + vr + '/min. The P waves went from about 83 to 107/min: the sinus node responded to the atropine. None of them reaches the ventricles, and the wide escape rhythm below the block has no vagal supply to remove. In complete infranodal block atropine costs time, and the treatment is pacing.', { bench: CB(true) }),
          multi('chb-wide', 'A wide rhythm at ' + vr + '/min', 'An 81-year-old is drowsy and cold, with a blood pressure of 74/40 mmHg. Atropine 1 mg has been given and nothing has improved.', [
            ['What is the wide, slow rhythm?', 'A ventricular escape rhythm below complete AV block', ['A slow ventricular tachycardia', 'Sinus bradycardia with a bundle branch block', 'Atrial fibrillation with a slow ventricular response'], 'P waves at their own faster rate, with no fixed relation to the QRS: complete AV block. The wide QRS is the rescue pacemaker in the ventricle. It is not an arrhythmia to be suppressed: an antiarrhythmic drug here can stop the heart.'],
            ['What now?', 'Transcutaneous pacing', ['More atropine, up to 6 mg', 'Amiodarone 300 mg IV', 'Synchronised cardioversion'], 'Pads on, pace, and confirm that each stimulus produces a pulse; electrical capture on the monitor is not enough. Give analgesia and sedation. An adrenaline or isoprenaline infusion can speed the escape rhythm while this is set up. Then a transvenous wire, then a permanent system.'],
            ['While the pads go on, which reversible causes do you look for?', 'Potassium, AV-nodal drugs, acute infarction', ['Thyrotoxicosis, anaemia, fever', 'Pulmonary embolism, hypovolaemia', 'Caffeine, alcohol, nicotine'], 'Hyperkalaemia, drugs (beta-blockers, verapamil, diltiazem, digoxin, antiarrhythmics) and myocardial infarction; less often hypothyroidism, hypothermia, Lyme disease or myocarditis. A reversible cause changes the long-term plan. It does not change the need to pace now.'],
          ], { bench: CB(false), tDone: 'Complete block with a ventricular escape: pace', why: 'A wide escape rhythm below complete AV block is paced; atropine does not reach it, and it must never be suppressed.' }),
          mcq('transplant', 'A denervated heart', 'Two years after a heart transplant, a patient has sinus bradycardia at 38/min with light-headedness and a blood pressure of 86/50 mmHg. Which is the logical first drug?',
            ['Isoprenaline (or aminophylline)', 'Atropine 1 mg, repeated to 3 mg', 'Glycopyrronium 0.4 mg IV', 'Adenosine 3 mg by rapid bolus'],
            'The transplanted heart is denervated: there is no vagal tone for atropine to remove, so it does nothing useful, paradoxical AV block has been reported, and guidelines advise against it. Drugs that act on the heart directly do work: a beta-agonist, or a methylxanthine such as aminophylline, which blocks adenosine receptors. Pacing if these fail.'),
          mcq('reversible', 'Treat the cause', rev[0], rev[1], rev[2]),
          mcq('ppm-who', 'Who needs a permanent pacemaker', 'Which of these patients has an indication for a permanent pacemaker?', ['Mobitz II block with a wide QRS, found by chance'].concat(ppm),
            'Acquired Mobitz II, high-grade and complete AV block that are not due to a reversible or transient cause are paced whether or not there are symptoms: the block is below the node, the escape rhythm is unreliable, and the first symptom may be syncope or death. Sinus node disease is paced only for symptoms that the bradycardia is shown to cause. Wenckebach in sleep or in athletes, first-degree block and asymptomatic sinus bradycardia are not indications, and block from infarction, drugs or potassium is given time to resolve.'),
        ];
      } },
  ];

  C.addTrack({ id: 'mgmt', title: 'Acute arrhythmia management', short: 'Management', dom: 'mgmt', bench: 'ecg',
    blurb: 'Drugs versus electricity: the first decision at the bedside, then each tachycardia and bradycardia in turn, with the reason the wrong treatment is dangerous.', units: UNITS });
})(globalThis.EP = globalThis.EP || {});
